// ==================================================
// ARCHITECTCONNECT
// PROPOSED ARCHITECTURE DECISION RECORD GENERATOR
//
// Purpose:
//
// Generate proposed ADR candidates from architecture
// evidence discovered by ArchitectConnect.
//
// Important:
//
// - ADRs generated here are always PROPOSED.
// - Repository evidence can establish what technology
//   or architectural approach is being used.
// - Repository evidence usually cannot establish why
//   the original team made that decision.
// - Historical rationale and alternatives therefore
//   require architect validation.
//
// ==================================================


// ==================================================
// ADD UNIQUE ADR
// ==================================================

function addUniqueAdr(
  adrs,
  candidate
) {

  if (
    !candidate ||
    !candidate.key
  ) {

    return;
  }


  const exists =
    adrs.some(
      (adr) =>
        adr.key ===
        candidate.key
    );


  if (!exists) {

    adrs.push(
      candidate
    );
  }
}


// ==================================================
// NORMALIZE STRING ARRAY
// ==================================================

function normalizeStringArray(
  value
) {

  if (!Array.isArray(value)) {

    return [];
  }


  return value
    .filter(
      (item) =>
        typeof item === "string" &&
        item.trim().length > 0
    )
    .map(
      (item) =>
        item.trim()
    );
}


// ==================================================
// NORMALIZE EVIDENCE
// ==================================================

function normalizeEvidence(
  evidence
) {

  return [
    ...new Set(
      normalizeStringArray(
        evidence
      )
    )
  ];
}


// ==================================================
// FIND APPLICATION BY FRAMEWORK
// ==================================================

function findApplicationByFramework(
  applications,
  framework
) {

  if (
    !Array.isArray(applications)
  ) {

    return null;
  }


  return (
    applications.find(
      (application) =>
        application &&
        application.framework ===
          framework
    ) ||
    null
  );
}


// ==================================================
// CREATE ADR CANDIDATE
// ==================================================

function createAdr({
  key,
  title,
  decision,
  context,
  evidence = [],
  observedConsequences = [],
  validationQuestions = []
}) {

  return {
    key,

    title,

    status:
      "Proposed",

    decision,

    context,

    evidence:
      normalizeEvidence(
        evidence
      ),

    rationale:
      "Historical rationale is not available from repository evidence.",

    alternatives:
      "Alternatives considered by the original architecture team are not available from repository evidence.",

    consequences: {

      observed:
        normalizeStringArray(
          observedConsequences
        ),

      requiresValidation:
        true
    },

    validationQuestions:
      normalizeStringArray(
        validationQuestions
      ),

    requiresValidation:
      true
  };
}


// ==================================================
// GENERATE PROPOSED ADRs
// ==================================================

function generateADRs(
  findings,
  metadata = {}
) {

  const adrs =
    [];


  const frameworks =
    normalizeStringArray(
      findings?.frameworks
    );


  const deployment =
    normalizeStringArray(
      findings?.deployment
    );


  const applications =
    Array.isArray(
      findings?.applications
    )
      ? findings.applications
      : [];


  // ==================================================
  // EXPRESS
  // ==================================================

  if (
    frameworks.includes(
      "Express"
    )
  ) {

    const application =
      findApplicationByFramework(
        applications,
        "Express"
      );


    addUniqueAdr(
      adrs,
      createAdr({

        key:
          "express-backend",

        title:
          "Use Express for the Backend API",

        decision:
          "Use Express as the web framework for the Node.js backend API.",

        context:
          "ArchitectConnect repository analysis detected an Express-based backend application.",

        evidence:
          application?.sourceFiles ||
          [],

        observedConsequences: [
          "HTTP API behavior is implemented using the Express framework.",
          "The backend application depends on the Node.js runtime."
        ],

        validationQuestions: [
          "Why was Express selected over other Node.js web frameworks?",
          "What performance, support, security, and maintainability requirements influenced this choice?"
        ]
      })
    );
  }


  // ==================================================
  // FASTAPI
  // ==================================================

  if (
    frameworks.includes(
      "FastAPI"
    )
  ) {

    const application =
      findApplicationByFramework(
        applications,
        "FastAPI"
      );


    addUniqueAdr(
      adrs,
      createAdr({

        key:
          "fastapi-python-api",

        title:
          "Use FastAPI for the Python API",

        decision:
          "Use FastAPI as the web framework for the Python API.",

        context:
          "ArchitectConnect repository analysis detected a FastAPI-based Python application.",

        evidence:
          application?.sourceFiles ||
          [],

        observedConsequences: [
          "The Python API uses FastAPI for HTTP endpoint implementation.",
          "The service requires a Python runtime."
        ],

        validationQuestions: [
          "Why was FastAPI selected for this API?",
          "Were Django, Flask, or other API frameworks considered?",
          "What performance and maintainability requirements influenced this choice?"
        ]
      })
    );
  }


  // ==================================================
  // REACT
  // ==================================================

  if (
    frameworks.includes(
      "React"
    )
  ) {

    const application =
      findApplicationByFramework(
        applications,
        "React"
      );


    addUniqueAdr(
      adrs,
      createAdr({

        key:
          "react-frontend",

        title:
          "Use React for the Frontend",

        decision:
          "Use React as the frontend application framework.",

        context:
          "ArchitectConnect repository analysis detected React as the frontend framework.",

        evidence: [
          ...(application?.sourceFiles || []),
          "package.json"
        ],

        observedConsequences: [
          "The frontend application uses the React component model.",
          "Frontend development depends on the JavaScript or TypeScript ecosystem."
        ],

        validationQuestions: [
          "Why was React selected over other frontend frameworks?",
          "What browser-support, maintainability, and user-experience requirements influenced this decision?"
        ]
      })
    );
  }


  // ==================================================
  // DOCKER
  // ==================================================

  if (
    deployment.includes(
      "Docker"
    )
  ) {

    addUniqueAdr(
      adrs,
      createAdr({

        key:
          "docker-containerization",

        title:
          "Containerize Application Workloads with Docker",

        decision:
          "Use Docker to package application workloads into containers.",

        context:
          "ArchitectConnect repository analysis detected Docker configuration.",

        evidence: [
          "Dockerfile"
        ],

        observedConsequences: [
          "Application runtime dependencies can be packaged into container images.",
          "Container-image build and lifecycle management become part of the delivery process."
        ],

        validationQuestions: [
          "Why was containerization selected for this application?",
          "What image-management and vulnerability-scanning policies apply?",
          "Where are container images stored and promoted?"
        ]
      })
    );
  }


  // ==================================================
  // KUBERNETES
  // ==================================================

  if (
    deployment.includes(
      "Kubernetes"
    )
  ) {

    addUniqueAdr(
      adrs,
      createAdr({

        key:
          "kubernetes-deployment",

        title:
          "Deploy Containerized Workloads with Kubernetes",

        decision:
          "Use Kubernetes for deployment of containerized application workloads.",

        context:
          "ArchitectConnect repository analysis detected Kubernetes deployment configuration.",

        evidence: [
          "k8s/deployment.yaml",
          "k8s/service.yaml"
        ],

        observedConsequences: [
          "Application deployment is represented using Kubernetes resources.",
          "Container orchestration becomes part of the runtime architecture."
        ],

        validationQuestions: [
          "Why was Kubernetes selected instead of another hosting platform?",
          "What availability and scaling requirements influenced this decision?",
          "What cluster-management and operational model is intended?",
          "What resource limits, probes, policies, and security controls are required?"
        ]
      })
    );
  }


  // ==================================================
  // TERRAFORM
  // ==================================================

  if (
    deployment.includes(
      "Terraform"
    )
  ) {

    addUniqueAdr(
      adrs,
      createAdr({

        key:
          "terraform-infrastructure",

        title:
          "Manage Infrastructure with Terraform",

        decision:
          "Use Terraform for infrastructure provisioning and management.",

        context:
          "ArchitectConnect repository analysis detected Terraform infrastructure definitions.",

        evidence: [
          "terraform/main.tf"
        ],

        observedConsequences: [
          "Infrastructure configuration is represented as declarative Terraform code.",
          "Terraform state management becomes an operational requirement."
        ],

        validationQuestions: [
          "Why was Terraform selected as an infrastructure-as-code technology?",
          "Where will Terraform state be stored?",
          "How will state locking and access control be implemented?",
          "Will reusable Terraform modules be used?"
        ]
      })
    );
  }


  // ==================================================
  // BICEP
  // ==================================================

  if (
    deployment.includes(
      "Bicep"
    )
  ) {

    addUniqueAdr(
      adrs,
      createAdr({

        key:
          "bicep-azure-infrastructure",

        title:
          "Use Bicep for Azure Infrastructure",

        decision:
          "Use Bicep for declarative Azure infrastructure definitions.",

        context:
          "ArchitectConnect repository analysis detected Bicep infrastructure definitions.",

        evidence: [
          "bicep/main.bicep"
        ],

        observedConsequences: [
          "Azure infrastructure configuration is represented declaratively using Bicep.",
          "Azure resource definitions become version-controlled architecture artifacts."
        ],

        validationQuestions: [
          "Why is Bicep used in addition to or instead of Terraform?",
          "What Azure resources are intended to remain Bicep-managed?",
          "How are responsibilities divided between Terraform and Bicep?",
          "Should common Bicep resources be organized into reusable modules?"
        ]
      })
    );
  }


  // ==================================================
  // ASSIGN ADR IDs + METADATA
  // ==================================================

  return adrs.map(
    (
      adr,
      index
    ) => ({

      id:
        `ADR-${String(
          index + 1
        ).padStart(
          3,
          "0"
        )}`,

      ...adr,

      repository:
        metadata.repository ||
        null,

      branch:
        metadata.branch ||
        null
    })
  );
}


// ==================================================
// EXPORT
// ==================================================

module.exports =
  generateADRs;

function analyzeBicep(contents) {
  const result = {
    detected: false,
    resources: []
  };

  for (const item of contents) {
    if (!item.path.endsWith(".bicep")) {
      continue;
    }

    const content = item.content || "";

    if (!content) {
      continue;
    }

    result.detected = true;

    const resourceRegex =
      /resource\s+(\w+)\s+'([^']+)'/g;

    let match;

    while (
      (match = resourceRegex.exec(content)) !== null
    ) {
      result.resources.push({
        name: match[1],
        type: match[2]
      });
    }
  }

  return result;
}

module.exports = analyzeBicep;

const path =
  require("path");


// ==================================================
// JAVASCRIPT / TYPESCRIPT IMPORT ANALYZER
//
// Purpose:
//
// Build repository-derived file dependency edges from:
//
// require("./localModule")
//
// import x from "./localModule"
//
// import { x } from "./localModule"
//
// import "./localModule"
//
// This analyzer does not depend on folder names such
// as controllers, services, repositories, backend,
// applications, or packages.
// ==================================================


// ==================================================
// NORMALIZE PATH
// ==================================================

function normalizePath(value) {
  return String(value || "")
    .replace(/\\/g, "/")
    .replace(/^\/+/, "");
}


// ==================================================
// GET FILE CONTENT
// ==================================================

function getFileContent(item) {
  if (!item) {
    return "";
  }

  if (
    typeof item.content === "string"
  ) {
    return item.content;
  }

  if (
    typeof item.text === "string"
  ) {
    return item.text;
  }

  return "";
}


// ==================================================
// JAVASCRIPT / TYPESCRIPT FILE CHECK
// ==================================================

function isJavaScriptFile(filePath) {
  const normalized =
    normalizePath(
      filePath
    ).toLowerCase();

  return (
    normalized.endsWith(".js") ||
    normalized.endsWith(".jsx") ||
    normalized.endsWith(".mjs") ||
    normalized.endsWith(".cjs") ||
    normalized.endsWith(".ts") ||
    normalized.endsWith(".tsx")
  );
}


// ==================================================
// EXTRACT REQUIRE IMPORTS
// ==================================================
//
// Examples:
//
// require("./http/users")
//
// require("../business/users")
//
// require('../data/users')
//
// ==================================================

function extractRequireImports(
  content
) {
  const imports = [];

  if (
    typeof content !== "string"
  ) {
    return imports;
  }


  // --------------------------------------------------
  // DOUBLE QUOTES
  // --------------------------------------------------

  const doubleQuoteRegex =
    /require\s*\(\s*"([^"]+)"\s*\)/g;

  let match;

  while (
    (
      match =
        doubleQuoteRegex.exec(
          content
        )
    ) !== null
  ) {
    if (match[1]) {
      imports.push(
        match[1]
      );
    }
  }


  // --------------------------------------------------
  // SINGLE QUOTES
  // --------------------------------------------------

  const singleQuoteRegex =
    /require\s*\(\s*'([^']+)'\s*\)/g;

  while (
    (
      match =
        singleQuoteRegex.exec(
          content
        )
    ) !== null
  ) {
    if (match[1]) {
      imports.push(
        match[1]
      );
    }
  }


  return imports;
}


// ==================================================
// EXTRACT ES MODULE IMPORTS
// ==================================================
//
// Supports:
//
// import users from "../business/users";
//
// import {
//   getUsers
// } from "../business/users";
//
// import * as users from "../business/users";
//
// import "../bootstrap";
//
// ==================================================

function extractEsImports(
  content
) {
  const imports = [];

  if (
    typeof content !== "string"
  ) {
    return imports;
  }


  // ==================================================
  // IMPORT ... FROM "..."
  // ==================================================

  const doubleQuoteFromRegex =
    /import\s+[\s\S]*?\s+from\s+"([^"]+)"/g;

  let match;

  while (
    (
      match =
        doubleQuoteFromRegex.exec(
          content
        )
    ) !== null
  ) {
    if (match[1]) {
      imports.push(
        match[1]
      );
    }
  }


  const singleQuoteFromRegex =
    /import\s+[\s\S]*?\s+from\s+'([^']+)'/g;

  while (
    (
      match =
        singleQuoteFromRegex.exec(
          content
        )
    ) !== null
  ) {
    if (match[1]) {
      imports.push(
        match[1]
      );
    }
  }


  // ==================================================
  // SIDE-EFFECT IMPORT
  //
  // import "./bootstrap";
  // ==================================================

  const doubleQuoteSideEffectRegex =
    /import\s+"([^"]+)"/g;

  while (
    (
      match =
        doubleQuoteSideEffectRegex.exec(
          content
        )
    ) !== null
  ) {
    if (match[1]) {
      imports.push(
        match[1]
      );
    }
  }


  const singleQuoteSideEffectRegex =
    /import\s+'([^']+)'/g;

  while (
    (
      match =
        singleQuoteSideEffectRegex.exec(
          content
        )
    ) !== null
  ) {
    if (match[1]) {
      imports.push(
        match[1]
      );
    }
  }


  return imports;
}


// ==================================================
// LOCAL IMPORT CHECK
// ==================================================
//
// Local:
//
// ./users
// ../business/users
//
// External:
//
// express
// react
// lodash
//
// ==================================================

function isLocalImport(
  importPath
) {
  if (
    typeof importPath !== "string"
  ) {
    return false;
  }

  return (
    importPath.startsWith("./") ||
    importPath.startsWith("../")
  );
}


// ==================================================
// RESOLVE IMPORT PATH
// ==================================================
//
// Example:
//
// Source:
//
// systems/account-service/src/http/users.js
//
// Import:
//
// ../business/users
//
// Resolved:
//
// systems/account-service/src/business/users.js
//
// ==================================================

function resolveImportPath(
  sourcePath,
  importPath,
  availablePaths
) {
  const normalizedSource =
    normalizePath(
      sourcePath
    );

  const sourceDirectory =
    path.posix.dirname(
      normalizedSource
    );


  const unresolvedTarget =
    normalizePath(
      path.posix.normalize(
        path.posix.join(
          sourceDirectory,
          importPath
        )
      )
    );


  // ==================================================
  // FILE RESOLUTION CANDIDATES
  // ==================================================

  const candidates = [
    unresolvedTarget,

    `${unresolvedTarget}.js`,
    `${unresolvedTarget}.jsx`,
    `${unresolvedTarget}.mjs`,
    `${unresolvedTarget}.cjs`,
    `${unresolvedTarget}.ts`,
    `${unresolvedTarget}.tsx`,

    `${unresolvedTarget}/index.js`,
    `${unresolvedTarget}/index.jsx`,
    `${unresolvedTarget}/index.mjs`,
    `${unresolvedTarget}/index.cjs`,
    `${unresolvedTarget}/index.ts`,
    `${unresolvedTarget}/index.tsx`
  ];


  for (
    const candidate of candidates
  ) {
    if (
      availablePaths.has(
        candidate
      )
    ) {
      return candidate;
    }
  }


  return null;
}


// ==================================================
// COLLECT IMPORT PATHS
// ==================================================

function collectImportPaths(
  content
) {
  const imports = [
    ...extractRequireImports(
      content
    ),

    ...extractEsImports(
      content
    )
  ];


  // ==================================================
  // REMOVE DUPLICATE IMPORT EXPRESSIONS
  // ==================================================

  return [
    ...new Set(imports)
  ];
}


// ==================================================
// MAIN ANALYZER
// ==================================================

function analyzeJavaScriptImports(
  contents
) {
  if (
    !Array.isArray(contents)
  ) {
    return [];
  }


  // ==================================================
  // BUILD REPOSITORY FILE INDEX
  // ==================================================

  const availablePaths =
    new Set();


  for (
    const item of contents
  ) {
    if (!item) {
      continue;
    }


    const filePath =
      normalizePath(
        item.path ||
        item.name ||
        ""
      );


    if (!filePath) {
      continue;
    }


    availablePaths.add(
      filePath
    );
  }


  // ==================================================
  // ANALYZE SOURCE IMPORTS
  // ==================================================

  const relationships = [];


  for (
    const item of contents
  ) {
    if (!item) {
      continue;
    }


    // --------------------------------------------------
    // SOURCE PATH
    // --------------------------------------------------

    const sourcePath =
      normalizePath(
        item.path ||
        item.name ||
        ""
      );


    if (!sourcePath) {
      continue;
    }


    // --------------------------------------------------
    // SOURCE TYPE
    // --------------------------------------------------

    if (
      !isJavaScriptFile(
        sourcePath
      )
    ) {
      continue;
    }


    // --------------------------------------------------
    // SOURCE CONTENT
    // --------------------------------------------------

    const content =
      getFileContent(
        item
      );


    if (!content) {
      continue;
    }


    // ==================================================
    // EXTRACT IMPORTS
    // ==================================================

    const imports =
      collectImportPaths(
        content
      );


    // ==================================================
    // PROCESS IMPORTS
    // ==================================================

    for (
      const importPath of imports
    ) {

      // ------------------------------------------------
      // Ignore external dependencies.
      //
      // Example:
      //
      // require("express")
      // import React from "react"
      //
      // Those belong to technology discovery.
      // ------------------------------------------------

      if (
        !isLocalImport(
          importPath
        )
      ) {
        continue;
      }


      // ------------------------------------------------
      // RESOLVE IMPORT TO ACTUAL REPOSITORY FILE
      // ------------------------------------------------

      const targetPath =
        resolveImportPath(
          sourcePath,
          importPath,
          availablePaths
        );


      // ------------------------------------------------
      // CREATE GRAPH EDGE
      // ------------------------------------------------

      relationships.push({
        from:
          sourcePath,

        to:
          targetPath,

        importPath,

        type:
          "source_import",

        relationship:
          "imports",

        resolved:
          Boolean(
            targetPath
          ),

        evidence:
          importPath
      });
    }
  }


  // ==================================================
  // REMOVE DUPLICATE GRAPH EDGES
  // ==================================================

  const uniqueRelationships =
    [];

  const seen =
    new Set();


  for (
    const relationship of
    relationships
  ) {
    const key =
      [
        relationship.from,

        relationship.to ||
          relationship.importPath
      ].join("|");


    if (
      seen.has(key)
    ) {
      continue;
    }


    seen.add(key);


    uniqueRelationships.push(
      relationship
    );
  }


  // ==================================================
  // RETURN IMPORT GRAPH
  // ==================================================

  return uniqueRelationships;
}


// ==================================================
// EXPORT
// ==================================================

module.exports =
  analyzeJavaScriptImports;

const path =
  require("path");


// ==================================================
// PYTHON IMPORT ANALYZER
//
// Purpose:
//
// Build repository-derived file dependency edges from:
//
// from app.logic.scoring import calculate_risk
// import app.logic.scoring
//
// The analyzer does not depend on folder names such
// as routers, services, repositories, python-api,
// applications, or packages.
// ==================================================


// ==================================================
// NORMALIZE PATH
// ==================================================

function normalizePath(value) {
  return String(value || "")
    .replace(/\\/g, "/")
    .replace(/^\/+/, "");
}


// ==================================================
// GET FILE CONTENT
// ==================================================

function getFileContent(item) {
  if (!item) {
    return "";
  }

  if (
    typeof item.content === "string"
  ) {
    return item.content;
  }

  if (
    typeof item.text === "string"
  ) {
    return item.text;
  }

  return "";
}


// ==================================================
// PYTHON FILE CHECK
// ==================================================

function isPythonFile(filePath) {
  return normalizePath(
    filePath
  )
    .toLowerCase()
    .endsWith(".py");
}


// ==================================================
// EXTRACT PYTHON IMPORTS
// ==================================================
//
// Supports:
//
// from app.logic.scoring import calculate_risk
//
// import app.logic.scoring
//
// from .logic import scoring
//
// from ..storage import risk_store
//
// ==================================================

function extractPythonImports(
  content
) {
  const imports = [];

  if (
    typeof content !== "string"
  ) {
    return imports;
  }

  const lines =
    content.split(/\r?\n/);

  for (
    const line of lines
  ) {
    const trimmed =
      line.trim();

    if (
      !trimmed ||
      trimmed.startsWith("#")
    ) {
      continue;
    }


    // ================================================
    // FROM X IMPORT Y
    // ================================================

    const fromMatch =
      trimmed.match(
        /^from\s+([^\s]+)\s+import\s+(.+)$/
      );

    if (fromMatch) {
  const importedValue =
    fromMatch[2].trim();

  imports.push({
    module:
      fromMatch[1],

    imported:
      importedValue === "("
        ? null
        : importedValue,

    statement:
      trimmed,

    syntax:
      "from"
  });

  continue;
}

    // ================================================
    // IMPORT X
    // ================================================

    const importMatch =
      trimmed.match(
        /^import\s+([^\s]+)/
      );

    if (importMatch) {
      imports.push({
        module:
          importMatch[1],

        imported:
          null,

        statement:
          trimmed,

        syntax:
          "import"
      });
    }
  }

  return imports;
}


// ==================================================
// EXTERNAL MODULE CHECK
// ==================================================
//
// These common modules are examples of dependencies
// that should not be interpreted as local source
// files.
//
// More importantly, resolution below verifies whether
// a corresponding repository file actually exists.
// ==================================================

function isObviouslyExternalModule(
  moduleName
) {
  const normalized =
    String(
      moduleName || ""
    ).toLowerCase();

  const knownExternalModules = [
    "fastapi",
    "flask",
    "django",
    "pydantic",
    "uvicorn",
    "requests",
    "sqlalchemy",
    "typing",
    "os",
    "sys",
    "json",
    "pathlib",
    "datetime",
    "collections"
  ];

  const topLevel =
    normalized
      .replace(/^\.+/, "")
      .split(".")[0];

  return knownExternalModules.includes(
    topLevel
  );
}


// ==================================================
// DETERMINE APPLICATION ROOT
// ==================================================
//
// Example:
//
// sourcePath:
// engines/risk-engine/app/endpoints/risk.py
//
// applicationRoot:
// engines/risk-engine
//
// ==================================================

function normalizeApplicationRoot(
  applicationRoot
) {
  return normalizePath(
    applicationRoot || ""
  ).replace(/\/+$/, "");
}


// ==================================================
// BUILD MODULE CANDIDATES
// ==================================================

function buildModuleCandidates(
  sourcePath,
  moduleName,
  importedName,
  applicationRoot
) {
  const candidates = [];

  const normalizedSource =
    normalizePath(
      sourcePath
    );

  const sourceDirectory =
    path.posix.dirname(
      normalizedSource
    );

  const normalizedRoot =
    normalizeApplicationRoot(
      applicationRoot
    );


  // ==================================================
  // RELATIVE PYTHON IMPORT
  //
  // Examples:
  //
  // from .logic import scoring
  // from ..storage import risk_store
  //
  // ==================================================

  if (
    moduleName.startsWith(".")
  ) {
    const leadingDots =
      (
        moduleName.match(
          /^\.+/
        ) || [""]
      )[0].length;

    const moduleWithoutDots =
      moduleName.slice(
        leadingDots
      );

    let baseDirectory =
      sourceDirectory;

    for (
      let index = 1;
      index < leadingDots;
      index++
    ) {
      baseDirectory =
        path.posix.dirname(
          baseDirectory
        );
    }

    if (moduleWithoutDots) {
      const modulePath =
        moduleWithoutDots.replace(
          /\./g,
          "/"
        );

      candidates.push(
        path.posix.join(
          baseDirectory,
          `${modulePath}.py`
        )
      );

      candidates.push(
        path.posix.join(
          baseDirectory,
          modulePath,
          "__init__.py"
        )
      );
    }

        if (
      importedName &&
      /^[a-zA-Z_][a-zA-Z0-9_]*$/.test(
        importedName
      )
    ) {
      const importedPath =
        importedName.replace(
          /\./g,
          "/"
        );

      if (moduleWithoutDots) {
        candidates.push(
          path.posix.join(
            baseDirectory,
            moduleWithoutDots.replace(
              /\./g,
              "/"
            ),
            `${importedPath}.py`
          )
        );
      } else {
        candidates.push(
          path.posix.join(
            baseDirectory,
            `${importedPath}.py`
          )
        );
      }
    }

    return candidates.map(
      normalizePath
    );
  }

 
  // ==================================================
  // ABSOLUTE APPLICATION IMPORT
  //
  // Examples:
  //
  // from app.logic.scoring import calculate_risk
  //
  // import app.logic.scoring
  //
  // ==================================================

  const modulePath =
    moduleName.replace(
      /\./g,
      "/"
    );

  if (normalizedRoot) {
    candidates.push(
      `${normalizedRoot}/${modulePath}.py`
    );

    candidates.push(
      `${normalizedRoot}/${modulePath}/__init__.py`
    );
  }

  candidates.push(
    `${modulePath}.py`
  );

  candidates.push(
    `${modulePath}/__init__.py`
  );


  // ==================================================
  // IMPORTED NAME MAY ITSELF BE A MODULE
  //
  // Example:
  //
  // from app.logic import scoring
  //
  // Candidate:
  //
  // app/logic/scoring.py
  // ==================================================

  if (
    importedName &&
    /^[a-zA-Z_][a-zA-Z0-9_]*$/.test(
      importedName
    )
  ) {
    const importedModulePath =
      `${modulePath}/${importedName}`;

    if (normalizedRoot) {
      candidates.push(
        `${normalizedRoot}/${importedModulePath}.py`
      );

      candidates.push(
        `${normalizedRoot}/${importedModulePath}/__init__.py`
      );
    }

    candidates.push(
      `${importedModulePath}.py`
    );

    candidates.push(
      `${importedModulePath}/__init__.py`
    );
  }


  return candidates.map(
    normalizePath
  );
}


// ==================================================
// RESOLVE PYTHON IMPORT
// ==================================================

function resolvePythonImport(
  sourcePath,
  importInfo,
  availablePaths,
  applicationRoot
) {
  if (
    !importInfo ||
    !importInfo.module
  ) {
    return null;
  }

  const importedNames =
    importInfo.imported
      ? importInfo.imported
          .split(",")
          .map(
            (value) =>
              value
                .trim()
                .split(/\s+as\s+/)[0]
                .trim()
          )
          .filter(Boolean)
      : [null];

  const candidateNames =
    importedNames.length > 0
      ? importedNames
      : [null];

  for (
    const importedName of
    candidateNames
  ) {
    const candidates =
      buildModuleCandidates(
        sourcePath,
        importInfo.module,
        importedName,
        applicationRoot
      );

    for (
      const candidate of
      candidates
    ) {
      if (
        availablePaths.has(
          candidate
        )
      ) {
        return candidate;
      }
    }
  }

  return null;
}


// ==================================================
// MAIN PYTHON IMPORT ANALYZER
// ==================================================

function analyzePythonImports(
  contents,
  applicationRoot = ""
) {
  if (
    !Array.isArray(contents)
  ) {
    return [];
  }


  // ==================================================
  // BUILD FILE INDEX
  // ==================================================

  const availablePaths =
    new Set();

  for (
    const item of contents
  ) {
    if (!item) {
      continue;
    }

    const filePath =
      normalizePath(
        item.path ||
        item.name ||
        ""
      );

    if (!filePath) {
      continue;
    }

    availablePaths.add(
      filePath
    );
  }


  // ==================================================
  // ANALYZE IMPORTS
  // ==================================================

  const relationships = [];

  for (
    const item of contents
  ) {
    if (!item) {
      continue;
    }

    const sourcePath =
      normalizePath(
        item.path ||
        item.name ||
        ""
      );

    if (
      !sourcePath ||
      !isPythonFile(
        sourcePath
      )
    ) {
      continue;
    }

    const content =
      getFileContent(
        item
      );

    if (!content) {
      continue;
    }

    const imports =
      extractPythonImports(
        content
      );

    for (
      const importInfo of imports
    ) {
      if (
        isObviouslyExternalModule(
          importInfo.module
        )
      ) {
        continue;
      }

      const targetPath =
        resolvePythonImport(
          sourcePath,
          importInfo,
          availablePaths,
          applicationRoot
        );

      relationships.push({
        from:
          sourcePath,

        to:
          targetPath,

        module:
          importInfo.module,

        imported:
          importInfo.imported,

        type:
          "source_import",

        relationship:
          "imports",

        resolved:
          Boolean(
            targetPath
          ),

        evidence:
          importInfo.statement
      });
    }
  }


  // ==================================================
  // REMOVE DUPLICATES
  // ==================================================

  const uniqueRelationships =
    [];

  const seen =
    new Set();

  for (
    const relationship of
    relationships
  ) {
    const key =
      [
        relationship.from,
        relationship.to ||
          relationship.module,
        relationship.evidence
      ].join("|");

    if (
      seen.has(key)
    ) {
      continue;
    }

    seen.add(key);

    uniqueRelationships.push(
      relationship
    );
  }


  return uniqueRelationships;
}


// ==================================================
// EXPORT
// ==================================================

module.exports =
  analyzePythonImports;

// ==================================================
// ARCHITECTCONNECT
// API -> COMPONENT RELATIONSHIP DISCOVERY
//
// Purpose:
//
// Connect dynamically discovered APIs to dynamically
// discovered request-handler components.
//
// Examples:
//
// GET /users
//     -> handled_by
// User Controller
//
// GET /users/
//     -> handled_by
// Users
//
// Evidence used:
//
// - application identity
// - API source
// - API handler
// - component source
// - component role
// - source import relationships
//
// Important:
//
// ArchitectConnect must not invent API -> component
// relationships when repository evidence is weak.
//
// ==================================================


// ==================================================
// NORMALIZE PATH
// ==================================================

function normalizePath(value) {
  return String(value || "")
    .replace(/\\/g, "/")
    .replace(/^\/+|\/+$/g, "")
    .toLowerCase();
}


// ==================================================
// GET BASE NAME WITHOUT EXTENSION
// ==================================================

function getBaseName(filePath) {
  const normalized =
    String(filePath || "")
      .replace(/\\/g, "/");

  const fileName =
    normalized
      .split("/")
      .pop() || "";

  return fileName
    .replace(/\.[^.]+$/, "");
}


// ==================================================
// NORMALIZE IDENTIFIER
// ==================================================
//
// Examples:
//
// userController
// User Controller
// user_controller
//
// become:
//
// usercontroller
//
// ==================================================

function normalizeIdentifier(value) {
  return String(value || "")
    .replace(/[^a-zA-Z0-9]/g, "")
    .toLowerCase();
}


// ==================================================
// SAME APPLICATION
// ==================================================

function belongsToApplication(
  item,
  application
) {
  if (
    !item ||
    !application
  ) {
    return false;
  }


  // ==================================================
  // APPLICATION ID
  // ==================================================

  if (
    item.applicationId &&
    application.id
  ) {
    return (
      item.applicationId ===
      application.id
    );
  }


  // ==================================================
  // APPLICATION ROOT
  // ==================================================

  const itemRoot =
    normalizePath(
      item.applicationRoot
    );

  const applicationRoot =
    normalizePath(
      application.root
    );


  if (
    itemRoot &&
    applicationRoot
  ) {
    return (
      itemRoot ===
      applicationRoot
    );
  }


  return true;
}


// ==================================================
// FIND REQUEST HANDLER BY SAME SOURCE
// ==================================================
//
// Strong evidence.
//
// FastAPI example:
//
// API:
//
// GET /users/
// source:
// app/routers/users.py
//
// Component:
//
// Users
// source:
// app/routers/users.py
// role:
// request_handler
//
// ==================================================

function findComponentBySource(
  api,
  components
) {
  if (!api) {
    return null;
  }


  const apiSource =
    normalizePath(
      api.source
    );


  if (!apiSource) {
    return null;
  }


  const matches =
    components.filter(
      (component) =>
        component &&
        component.role ===
          "request_handler" &&
        normalizePath(
          component.source
        ) ===
          apiSource
    );


  if (
    matches.length === 1
  ) {
    return matches[0];
  }


  return null;
}


// ==================================================
// FIND REQUEST HANDLER FROM HANDLER NAME
// ==================================================
//
// Express example:
//
// API handler:
//
// userController.getUsers
//
// Component:
//
// User Controller
//
// Component source:
//
// userController.js
//
// ==================================================

function findComponentByHandler(
  api,
  components
) {
  if (
    !api ||
    !api.handler ||
    !Array.isArray(components)
  ) {
    return null;
  }


  // ==================================================
  // HANDLER
  // ==================================================
  //
  // Examples:
  //
  // users.getUsers
  // userController.getUsers
  //
  // ==================================================

  const handler =
    String(
      api.handler
    ).trim();


  if (!handler) {
    return null;
  }


  // ==================================================
  // HANDLER OBJECT
  // ==================================================
  //
  // users.getUsers
  //
  // becomes:
  //
  // users
  //
  // userController.getUsers
  //
  // becomes:
  //
  // userController
  //
  // ==================================================

  const handlerObject =
    handler
      .split(".")[0]
      .trim();


  if (!handlerObject) {
    return null;
  }


  const normalizedHandlerObject =
    normalizeIdentifier(
      handlerObject
    );

  // ==================================================
  // FIND REQUEST HANDLER COMPONENT
  // ==================================================

  const matches =
    components.filter(
      (component) => {
        if (
          !component ||
          component.role !==
            "request_handler"
        ) {
          return false;
        }


        // ==============================================
        // COMPONENT DISPLAY NAME
        // ==============================================

        const normalizedComponentName =
          normalizeIdentifier(
            component.name
          );


        // ==============================================
        // COMPONENT FILE NAME
        // ==============================================

        const componentBaseName =
          getBaseName(
            component.source
          );


        const normalizedComponentBaseName =
          normalizeIdentifier(
            componentBaseName
          );


        // ==============================================
        // EXACT MATCH
        // ==============================================

        if (
          normalizedComponentName ===
            normalizedHandlerObject ||
          normalizedComponentBaseName ===
            normalizedHandlerObject
        ) {
          return true;
        }


        // ==============================================
        // CONTROLLER SUFFIX NORMALIZATION
        // ==============================================
        //
        // Handler:
        //
        // userController.getUsers
        //
        // Component:
        //
        // User Controller
        //
        // Also supports:
        //
        // users.getUsers
        //
        // Component:
        //
        // Users
        //
        // ==============================================

        const handlerWithoutController =
          normalizedHandlerObject.replace(
            /controller$/,
            ""
          );


        const componentWithoutController =
          normalizedComponentName.replace(
            /controller$/,
            ""
          );


        const fileWithoutController =
          normalizedComponentBaseName.replace(
            /controller$/,
            ""
          );


        return (
          handlerWithoutController &&
          (
            handlerWithoutController ===
              componentWithoutController ||
            handlerWithoutController ===
              fileWithoutController
          )
        );
      }
    );


  // ==================================================
  // ONLY ACCEPT UNAMBIGUOUS MATCH
  // ==================================================

  if (
    matches.length === 1
  ) {
    return matches[0];
  }


  return null;
}



// ==================================================
// FIND REQUEST HANDLER FROM IMPORT GRAPH
// ==================================================
//
// This is weaker evidence than direct handler matching.
//
// Example:
//
// server.js
//     -> imports
// userController.js
//
// Only use this fallback when an API already has an
// explicit named handler.
//
// ==================================================

function findComponentFromImports(
  api,
  components,
  sourceRelationships
) {
  if (!api) {
    return null;
  }


  const apiSource =
    normalizePath(
      api.source
    );


  if (!apiSource) {
    return null;
  }


  // ==================================================
  // IMPORTED FILES
  // ==================================================

  const importedTargets =
    sourceRelationships
      .filter(
        (relationship) =>
          relationship &&
          relationship.resolved ===
            true &&
          normalizePath(
            relationship.from
          ) ===
            apiSource &&
          relationship.to
      )
      .map(
        (relationship) =>
          normalizePath(
            relationship.to
          )
      );


  if (
    importedTargets.length === 0
  ) {
    return null;
  }


  // ==================================================
  // MATCH REQUEST HANDLER
  // ==================================================

  const matches =
    components.filter(
      (component) =>
        component &&
        component.role ===
          "request_handler" &&
        importedTargets.includes(
          normalizePath(
            component.source
          )
        )
    );


  if (
    matches.length === 1
  ) {
    return matches[0];
  }


  return null;
}


// ==================================================
// FIND HANDLER COMPONENT
