// ==================================================
// APPLICATION ID
// ==================================================

function createApplicationId(
  root,
  runtime
) {
  const safeRoot =
    normalizePath(root)
      .replace(
        /[^a-zA-Z0-9]+/g,
        "-"
      )
      .replace(
        /^-+|-+$/g,
        ""
