  return `${safeRuntime}-${safeRoot || "root"}`;
}


// ==================================================
// DISCOVER NODE ROOTS
// ==================================================

function discoverNodeRoots(
  contents
) {
  const roots = [];

  for (const item of contents) {
    const path =
      normalizePath(
        item.path ||
        item.name
      );

    if (
      path
        .toLowerCase()
        .endsWith("package.json")
    ) {
      const root =
        getDirectory(path);

      if (!roots.includes(root)) {
        roots.push(root);
      }
    }
  }

  return roots;
}


// ==================================================
// DISCOVER PYTHON ROOTS
// ==================================================

function discoverPythonRoots(
  contents
) {
  const roots = [];

  const projectFiles = [
    "requirements.txt",
    "pyproject.toml",
    "pipfile",
    "setup.py"
  ];

  for (const item of contents) {
    const path =
      normalizePath(
        item.path ||
        item.name
      );

    const lower =
      path.toLowerCase();

    const match =
      projectFiles.some(
        (name) =>
          lower.endsWith(name)
      );

    if (!match) {
      continue;
    }

    const root =
      getDirectory(path);

    if (!roots.includes(root)) {
      roots.push(root);
    }
  }

  return roots;
}


// ==================================================
