    discoverNodeRoots(
      contents
    );

  for (const root of nodeRoots) {
    const files =
      getFilesInsideRoot(
        contents,
        root
      );

    const technology =
      discoverNodeTechnology(
        files
      );

    if (!technology.detected) {
      continue;
    }

    applications.push({
      id:
        createApplicationId(
          root,
          technology.runtime
        ),

      root,

      language:
        technology.language,

      runtime:
        technology.runtime,

      framework:
        technology.framework,

      type:
        technology.type,

      confidence:
        technology.confidence,

      evidence:
        technology.evidence,

      files:
        files.map(
          (item) =>
            item.path ||
            item.name
        )
    });
  }


  // ==================================================
  // PYTHON APPLICATIONS
  // ==================================================

  const pythonRoots =
    discoverPythonRoots(
      contents
    );

  for (
