  const result = [];

  const seen =
    new Set();

  for (
    const relationship of
    relationships
  ) {
    if (!relationship) {
      continue;
    }

    const key =
  [
    relationship.applicationId,
    relationship.from,
    relationship.to,
    relationship.fromType,
    relationship.toType,
    relationship.relationship,
    relationship.sourceFrom ||
      relationship.source ||
      "",
    relationship.sourceTo ||
      relationship.componentSource ||
      ""
  ].join("|");

    if (
      seen.has(key)
    ) {
      continue;
    }

    seen.add(key);

    result.push(
      relationship
