  if (
    items.length === 0
  ) {
    return {
      valid:
        false,

      reason:
        "No architecture relationships were available."
    };
  }


  for (
    const relationship of items
  ) {
    if (
      !relationship ||
      !relationship.from ||
      !relationship.to ||
      !relationship.relationship
    ) {
      return {
        valid:
          false,

        reason:
          "One or more architecture relationships are incomplete."
      };
    }
  }


  return {
    valid:
      true,

    reason:
      null
  };
}


// ==================================================
// VALIDATE DYNAMIC PROJECTION
// ==================================================

function validateDynamicProjection(
  projection
) {
  if (
    !projection ||
    typeof projection !== "object"
  ) {
    return {
      valid:
        false,

      reason:
        "Dynamic architecture projection is missing."
    };
  }


  const applications =
    safeArray(
      projection.applications
    );

  const apis =
    safeArray(
      projection.apis
    );

  const components =
    safeArray(
      projection.components
    );

  const relationships =
    safeArray(
      projection.relationships
    );


  // ==================================================
  // APPLICATIONS
  // ==================================================

  if (
    applications.length === 0
  ) {
    return {
      valid:
        false,

      reason:
        "Dynamic architecture contains no applications."
    };
  }


  // ==================================================
  // COMPONENTS
  // ==================================================

  if (
    components.length === 0
  ) {
    return {
      valid:
        false,

      reason:
        "Dynamic architecture contains no components."
    };
  }


  // ==================================================
  // APPLICATION VALIDATION
  // ==================================================

  for (
    const application of applications
  ) {
    if (
      !application ||
      !application.id ||
      !application.root
    ) {
      return {
        valid:
          false,

        reason:
          "One or more dynamic applications are incomplete."
      };
    }
  }


  // ==================================================
  // COMPONENT VALIDATION
  // ==================================================

  for (
    const component of components
  ) {
    if (
      !component ||
      !component.name ||
      !component.type ||
      !component.applicationId
    ) {
      return {
        valid:
          false,

        reason:
          "One or more dynamic components are incomplete."
      };
    }
  }


  // ==================================================
  // API VALIDATION
  // ==================================================

  for (
    const api of apis
  ) {
    if (
      !api ||
      !api.applicationId ||
      !api.method ||
      !api.path
    ) {
      return {
        valid:
          false,

        reason:
          "One or more dynamic APIs are incomplete."
      };
    }
