// ==================================================
// ENTRY POINT DETECTION
// ==================================================

function isEntryPoint(filePath) {
  const fileName =
    getFileName(filePath)
      .toLowerCase();

  return (
    fileName === "server.js" ||
    fileName === "server.ts" ||
    fileName === "index.js" ||
    fileName === "index.ts" ||
    fileName === "main.py" ||
    fileName === "app.py"
