    );
  }

  if (
    !Array.isArray(
      relationships
    )
  ) {
    return graph;
  }

  for (
    const relationship of relationships
  ) {
    if (
      !relationship ||
      !relationship.resolved ||
      !relationship.from ||
      !relationship.to
    ) {
      continue;
    }

    const from =
      normalizePath(
        relationship.from
      );

    const to =
      normalizePath(
        relationship.to
      );

    if (!graph.has(from)) {
      graph.set(
        from,
        {
          incoming: [],
          outgoing: []
        }
      );
    }

    if (!graph.has(to)) {
      graph.set(
        to,
        {
          incoming: [],
          outgoing: []
        }
      );
    }

    graph
      .get(from)
      .outgoing
      .push(to);

    graph
      .get(to)
      .incoming
      .push(from);
  }

  return graph;
}


// ==================================================
