      ? graphInfo.incoming
      : [];

  const outgoing =
    Array.isArray(
      graphInfo.outgoing
    )
      ? graphInfo.outgoing
      : [];

  const evidence = [];


  // ==================================================
  // ENTRYPOINT
  // ==================================================

  if (
    isEntryPoint(
      filePath
    )
  ) {
    evidence.push(
      "Application entry-point filename detected."
    );

    if (
      outgoing.length > 0
    ) {
      evidence.push(
        "Entrypoint imports internal application modules."
      );
    }

    return {
      role:
        "entrypoint",

      confidence:
        outgoing.length > 0
          ? 0.95
          : 0.85,

      evidence
    };
  }


  // ==================================================
  // REQUEST HANDLER
  // ==================================================

  if (
    hints.request
  ) {
    evidence.push(
      "Request/endpoint-oriented path evidence detected."
    );

    if (
      incoming.length > 0
    ) {
      evidence.push(
        "Component is imported by another internal application module."
      );
    }

    if (
      outgoing.length > 0
    ) {
      evidence.push(
        "Component delegates to another internal application module."
      );
    }

    return {
      role:
        "request_handler",

      confidence:
        incoming.length > 0 &&
        outgoing.length > 0
          ? 0.95
          : 0.8,

      evidence
    };
  }


  // ==================================================
  // BUSINESS COMPONENT
  // ==================================================

  if (
    hints.business
  ) {
    evidence.push(
      "Business/domain-oriented path evidence detected."
    );

    if (
      incoming.length > 0 &&
      outgoing.length > 0
    ) {
      evidence.push(
        "Component sits between upstream and downstream internal modules."
      );
    }

    return {
      role:
        "business_component",

      confidence:
        incoming.length > 0 &&
        outgoing.length > 0
          ? 0.95
          : 0.8,

      evidence
    };
  }


  // ==================================================
  // DATA COMPONENT
  // ==================================================

  if (
    hints.data
  ) {
    evidence.push(
      "Data/storage-oriented path evidence detected."
    );

    if (
      incoming.length > 0
    ) {
      evidence.push(
        "Component is consumed by an upstream internal module."
      );
    }

    if (
      outgoing.length === 0
    ) {
      evidence.push(
        "Component is a downstream leaf in the internal dependency graph."
      );
    }

    return {
      role:
        "data_component",

      confidence:
        incoming.length > 0 &&
        outgoing.length === 0
          ? 0.95
          : 0.8,

      evidence
    };
  }


  // ==================================================
  // GRAPH-BASED FALLBACK
  // ==================================================
  //
  // No semantic directory name was recognized.
  // Use dependency topology as weaker evidence.
  // ==================================================

  if (
    incoming.length > 0 &&
    outgoing.length > 0
  ) {
    evidence.push(
      "Component has both incoming and outgoing internal dependencies."
    );

    return {
      role:
        "internal_component",

      confidence:
        0.65,

      evidence
    };
  }


  if (
    incoming.length > 0 &&
    outgoing.length === 0
  ) {
    evidence.push(
      "Component is a downstream leaf in the dependency graph."
    );

    return {
      role:
        "internal_component",

      confidence:
        0.55,

      evidence
    };
  }


  if (
    incoming.length === 0 &&
    outgoing.length > 0
  ) {
    evidence.push(
      "Component initiates internal dependencies."
    );

    return {
      role:
        "internal_component",

      confidence:
        0.55,

      evidence
    };
  }


  evidence.push(
    "Insufficient repository dependency evidence for a specialized role."
  );

  return {
    role:
      "internal_component",

    confidence:
      0.4,

    evidence
