  // Final expected architecture:
  //
  // GET /users/
  //      |
  //      | handled_by
  //      v
  // Users Router
  //      |
  //      | uses
  //      v
  // User Service
  //      |
  //      | uses
  //      v
  // User Repository
  //
  // ==================================================

  const allDependencies = [
    ...routeDependencies,
    ...(
      Array.isArray(
        codeDependencies
      )
        ? codeDependencies
        : []
    )
  ];

  // ==================================================
  // SOURCE FILE LIST
  // ==================================================

  const sourceFiles =
    pythonFiles.map(
      (file) =>
        file.path ||
        file.name
    );

  // ==================================================
  // DEPENDENCY FILE LIST
  // ==================================================

  const dependencyFilePaths =
    dependencyFiles.map(
      (file) =>
        file.path ||
        file.name
    );

  // ==================================================
  // RETURN PYTHON APPLICATION ANALYSIS
  // ==================================================

  return {
    detected,

    application:
      detected
        ? "Python API"
        : null,

    language:
      detected
        ? "Python"
        : null,

    runtime:
      detected
        ? "Python"
        : null,

    framework:
      fastApi &&
      fastApi.detected
        ? "FastAPI"
        : null,

    // ================================================
    // SOURCE FILES
    // ================================================

    sourceFiles,

    // ================================================
    // PYTHON PROJECT / DEPENDENCY FILES
    // ================================================

    dependencyFiles:
      dependencyFilePaths,

    // ================================================
    // API ROUTES
    // FR-AC-003
    // ================================================

    routes:
      fastApi &&
      Array.isArray(
        fastApi.routes
      )
        ? fastApi.routes
        : [],

    // ================================================
    // APPLICATION COMPONENTS
    // FR-AC-004
    // ================================================

    components:
      Array.isArray(
        components
      )
        ? components
        : [],

    // ================================================
    // APPLICATION DEPENDENCIES
    // FR-AC-005
    // ================================================

    dependencies:
      allDependencies
  };
}

