function analyzePython(contents) {
  const filePaths = contents.map((item) =>
    (item.path || item.name || "").toLowerCase()
  );

  // --------------------------------------------------
  // Python Source Detection
  // --------------------------------------------------

  const pythonFiles = filePaths.filter((file) =>
    file.endsWith(".py")
  );

  // --------------------------------------------------
  // Python Dependency / Project File Detection
  // --------------------------------------------------

  const dependencyFiles = filePaths.filter((file) =>
    file.endsWith("requirements.txt") ||
    file.endsWith("pyproject.toml") ||
    file.endsWith("pipfile") ||
    file.endsWith("setup.py")
  );

  // --------------------------------------------------
  // Python Detection
  // --------------------------------------------------

  const detected =
    pythonFiles.length > 0 ||
    dependencyFiles.length > 0;

  // --------------------------------------------------
  // Confidence
  // --------------------------------------------------

  let confidence = 0;

  if (
    pythonFiles.length > 0 &&
    dependencyFiles.length > 0
  ) {
    confidence = 1.0;
  } else if (pythonFiles.length > 0) {
    confidence = 0.8;
  } else if (dependencyFiles.length > 0) {
    confidence = 0.6;
  }

  // --------------------------------------------------
  // Evidence
  // --------------------------------------------------

  const evidence = [];

  if (pythonFiles.length > 0) {
    evidence.push(
      `${pythonFiles.length} Python source file(s) found`
    );
  }

  if (dependencyFiles.length > 0) {
    evidence.push(
      `${dependencyFiles.length} Python dependency/project file(s) found`
    );
  }

  // --------------------------------------------------
  // Result
  // --------------------------------------------------

  return {
    detected,
    language: detected ? "Python" : "",
    confidence,
    sourceFiles: pythonFiles,
    dependencyFiles,
    frameworks: [],
    evidence
  };
}

module.exports = analyzePython;

function analyzeTerraform(contents) {
  const result = {
    detected: false,
    providers: [],
    resources: []
  };

  for (const item of contents) {
    if (!item.path.endsWith(".tf")) {
      continue;
    }

    const content = item.content || "";

    if (!content) {
      continue;
    }

    result.detected = true;

    const providerRegex =
      /provider\s+"([^"]+)"/g;

    let providerMatch;

    while (
      (providerMatch = providerRegex.exec(content)) !== null
    ) {
      if (
        !result.providers.includes(providerMatch[1])
      ) {
        result.providers.push(providerMatch[1]);
      }
    }

    const resourceRegex =
      /resource\s+"([^"]+)"\s+"([^"]+)"/g;

    let resourceMatch;

    while (
      (resourceMatch = resourceRegex.exec(content)) !== null
    ) {
      result.resources.push({
        type: resourceMatch[1],
        name: resourceMatch[2]
      });
    }
  }

  return result;
}

