function shouldLoadContent(path) {
  const normalizedPath =
    String(path || "")
      .replace(/\\/g, "/")
      .toLowerCase();

  // --------------------------------------------------
  // Node / JavaScript project files
  // --------------------------------------------------

  if (
    normalizedPath.endsWith(
      "package.json"
    ) ||
    normalizedPath.endsWith(
      "yarn.lock"
    )
  ) {
    return true;
  }

  // --------------------------------------------------
  // JavaScript / TypeScript source
  // --------------------------------------------------

  if (
    normalizedPath.endsWith(
      ".js"
    ) ||
    normalizedPath.endsWith(
      ".jsx"
    ) ||
    normalizedPath.endsWith(
      ".ts"
    ) ||
    normalizedPath.endsWith(
      ".tsx"
    ) ||
    normalizedPath.endsWith(
      ".mjs"
    ) ||
    normalizedPath.endsWith(
      ".cjs"
    )
  ) {
    return true;
  }

  // --------------------------------------------------
  // Python source
  // --------------------------------------------------

  if (
    normalizedPath.endsWith(
      ".py"
    )
  ) {
    return true;
  }

  // --------------------------------------------------
  // Python dependency / project files
  // --------------------------------------------------

  if (
    normalizedPath.endsWith(
      "requirements.txt"
    ) ||
    normalizedPath.endsWith(
      "pyproject.toml"
    ) ||
    normalizedPath.endsWith(
      "pipfile"
    ) ||
    normalizedPath.endsWith(
      "pipfile.lock"
    ) ||
    normalizedPath.endsWith(
      "poetry.lock"
    ) ||
    normalizedPath.endsWith(
      "uv.lock"
    ) ||
    normalizedPath.endsWith(
      "setup.py"
    ) ||
    normalizedPath.endsWith(
      "setup.cfg"
    )
  ) {
    return true;
  }

  // --------------------------------------------------
  // Docker
  // --------------------------------------------------

  if (
    normalizedPath ===
      "dockerfile" ||
    normalizedPath.endsWith(
      "/dockerfile"
    ) ||
    normalizedPath.endsWith(
      ".dockerfile"
    )
  ) {
    return true;
  }

  // --------------------------------------------------
  // Terraform
  // --------------------------------------------------

  if (
    normalizedPath.endsWith(
      ".tf"
    ) ||
    normalizedPath.endsWith(
      ".tfvars"
    )
  ) {
    return true;
  }

  // --------------------------------------------------
  // Azure Bicep
  // --------------------------------------------------

  if (
    normalizedPath.endsWith(
      ".bicep"
    )
  ) {
    return true;
  }

  // --------------------------------------------------
  // Kubernetes / YAML
  // --------------------------------------------------

  if (
    normalizedPath.endsWith(
      ".yaml"
    ) ||
    normalizedPath.endsWith(
      ".yml"
    )
  ) {
    return true;
  }

  return false;
}

