async function loadBlobContent(
  sha,
  path
) {
  try {
    const response =
      await octokit.git.getBlob({
        owner:
          OWNER,

        repo:
          REPO,

        file_sha:
          sha
      });

    if (
      !response.data.content
    ) {
      return "";
    }

    const encoding =
      response.data.encoding ||
      "base64";

    return Buffer.from(
      response.data.content,
      encoding
    ).toString(
      "utf8"
    );
  } catch (error) {
    console.warn(
      `[WARNING] Unable to read ${path}: ${error.message}`
    );

    return "";
  }
}

