    });

  if (
    treeResponse.data.truncated
  ) {
    console.warn(
      "\nWARNING: GitHub returned a truncated repository tree."
    );

    console.warn(
      "Some repository files may not be included in the architecture analysis."
    );
  }

  const tree =
    treeResponse.data.tree ||
    [];

  // ==================================================
  // ACTUAL FILES
  // ==================================================

  const repositoryFiles =
    tree.filter(
      (item) =>
        item.type ===
        "blob"
    );

  console.log(
    `Repository files discovered: ${repositoryFiles.length}`
  );

  // ==================================================
  // NORMALIZE FILE OBJECTS
  // ==================================================

  const contents =
    repositoryFiles.map(
      (file) => {
        const path =
          file.path ||
          "";

        const pathParts =
          path.split(
            "/"
          );

        const name =
          pathParts[
            pathParts.length -
            1
          ] ||
          path;

        return {
          name,
          path,
          type:
            "file",
          sha:
            file.sha,
          size:
            file.size ||
            0,
          content:
            ""
        };
      }
    );

  // ==================================================
  // ARCHITECTURE FILES
  // ==================================================

  const relevantFiles =
    contents.filter(
      (file) =>
        shouldLoadContent(
          file.path
        )
    );

  console.log(
    `Architecture-relevant files: ${relevantFiles.length}`
  );

  console.log(
    "\nLoading architecture-relevant file contents...\n"
  );

  // ==================================================
  // DOWNLOAD CONTENT
  // ==================================================

  for (
    const file of
    relevantFiles
  ) {
    file.content =
      await loadBlobContent(
        file.sha,
        file.path
      );

    console.log(
      `${
        file.content
          ? "[OK]"
          : "[NO CONTENT]"
      } ${file.path}`
    );
  }

  console.log(
    "\nRepository loading complete.\n"
  );

  return {
    contents,
    defaultBranch,
    treeSha,

    repository: {
      owner:
        OWNER,

      name:
        REPO,

      fullName:
        `${OWNER}/${REPO}`
    }
  };
}

// ==================================================
// GET ROOT PACKAGE.JSON
// ==================================================

function getPackageContent(
  contents
) {
  const packageFile =
    contents.find(
      (item) => {
        const normalizedPath =
          String(
            item.path ||
            ""
          )
            .replace(
              /\\/g,
              "/"
            )
            .toLowerCase();

        return (
          normalizedPath ===
          "package.json"
        );
      }
    );

  return (
    packageFile?.content ||
    ""
  );
}

