    "\n========== ARCHITECTURE FILES ==========\n"
  );

  const relevantFiles =
    contents.filter(
      (file) =>
        shouldLoadContent(
          file.path
        )
    );

  for (
    const file of
    relevantFiles
  ) {
    console.log(
      file.path
    );
  }

  console.log(
    "\n========================================\n"
  );

  // ==================================================
  // PYTHON SOURCE FILES
  // ==================================================

  const pythonFiles =
    contents.filter(
      (file) =>
        String(
          file.path ||
          ""
        )
          .replace(
            /\\/g,
            "/"
          )
          .toLowerCase()
          .endsWith(
            ".py"
          )
    );

  console.log(
    `Python files discovered: ${pythonFiles.length}`
  );

  for (
    const file of
    pythonFiles
  ) {
    console.log(
      `  - ${file.path}`
    );
  }

  // ==================================================
  // PYTHON DEPENDENCY FILES
  // ==================================================

  const pythonDependencyFiles =
    contents.filter(
      (file) => {
        const path =
          String(
            file.path ||
            ""
          )
            .replace(
              /\\/g,
              "/"
            )
            .toLowerCase();

        return (
          path.endsWith(
            "requirements.txt"
          ) ||
          path.endsWith(
            "pyproject.toml"
          ) ||
          path.endsWith(
            "pipfile"
          ) ||
          path.endsWith(
            "pipfile.lock"
          ) ||
          path.endsWith(
            "poetry.lock"
          ) ||
          path.endsWith(
            "uv.lock"
          ) ||
          path.endsWith(
            "setup.py"
          ) ||
          path.endsWith(
            "setup.cfg"
          )
        );
      }
    );

  console.log(
    `\nPython dependency files discovered: ${pythonDependencyFiles.length}`
  );

  for (
    const file of
    pythonDependencyFiles
  ) {
    console.log(
      `  - ${file.path}`
    );
  }

  // ==================================================
  // VERIFY PYTHON CONTENT
  // ==================================================

  if (
    pythonFiles.length >
    0
  ) {
    console.log(
      "\nPython source content check:"
    );

    for (
      const file of
      pythonFiles
    ) {
      console.log(
        `  ${
          file.content
            ? "[AVAILABLE]"
            : "[NOT AVAILABLE]"
        } ${file.path}`
      );
    }
  }

  console.log("");
}

