const fs = require("fs");
const path = require("path");

const scanRepository = require("./repositoryScanner");
const generateHLD = require("./hldGenerator");
const generateStructurizr = require("./structurizrGenerator");
const saveReport = require("./reportGenerator");

const analyzeDocker = require("./analyzers/dockerAnalyzer");
const analyzeKubernetes = require("./analyzers/kubernetesAnalyzer");
const analyzeTerraform = require("./analyzers/terraformAnalyzer");
const analyzeBicep = require("./analyzers/bicepAnalyzer");

const buildArchitectureModel = require(
  "./models/architectureModel"
);

const REPOSITORY_PATH = path.resolve(
  __dirname,
  "..",
  "architectconnect-sample-app"
);

function readRepository(directory, rootDirectory) {
  const results = [];

  const entries = fs.readdirSync(directory, {
    withFileTypes: true
  });

  for (const entry of entries) {
    if (
      entry.name === "node_modules" ||
      entry.name === ".git"
    ) {
      continue;
    }

    const fullPath = path.join(
      directory,
      entry.name
    );

    const relativePath = path
      .relative(rootDirectory, fullPath)
      .replace(/\\/g, "/");

    if (entry.isDirectory()) {
      results.push({
        name: entry.name,
        path: relativePath,
        type: "dir"
      });

      const childItems = readRepository(
        fullPath,
        rootDirectory
      );

      results.push(...childItems);
    } else {
      let content = "";

      try {
        content = fs.readFileSync(
          fullPath,
          "utf8"
        );
      } catch (error) {
        content = "";
      }

      results.push({
        name: entry.name,
        path: relativePath,
        type: "file",
        content
      });
    }
  }

  return results;
}

function readPackageJson(repositoryPath) {
  const packagePath = path.join(
    repositoryPath,
    "package.json"
  );

  if (!fs.existsSync(packagePath)) {
    return "";
  }

  return fs.readFileSync(
    packagePath,
    "utf8"
  );
}

async function runArchitectConnectLocal() {
  try {
    console.log(
      "\nArchitectConnect Local Analysis"
    );

    console.log(
      "===============================\n"
    );

    console.log(
      `Repository: ${REPOSITORY_PATH}\n`
    );

    if (!fs.existsSync(REPOSITORY_PATH)) {
      throw new Error(
        `Repository not found: ${REPOSITORY_PATH}`
      );
    }

    // Read repository
    const contents = readRepository(
      REPOSITORY_PATH,
      REPOSITORY_PATH
    );

    const packageContent =
      readPackageJson(REPOSITORY_PATH);

    console.log("Repository Contents\n");

    contents.forEach((item) => {
      console.log(
        `${item.type} - ${item.path}`
      );
    });

    // General repository analysis
    const findings = scanRepository(
      contents,
      packageContent.toLowerCase()
    );

    // Docker
    const dockerFile = contents.find(
      (item) =>
        item.type === "file" &&
        item.name.toLowerCase() === "dockerfile"
    );

    const dockerAnalysis =
      analyzeDocker(
        dockerFile?.content || ""
      );

    // Kubernetes
    const kubernetesAnalysis =
      analyzeKubernetes(contents);

    // Terraform
    const terraformAnalysis =
      analyzeTerraform(contents);

    // Bicep
    const bicepAnalysis =
      analyzeBicep(contents);

    // Add infrastructure findings
    findings.infrastructure = {
      docker: dockerAnalysis,
      kubernetes: kubernetesAnalysis,
      terraform: terraformAnalysis,
      bicep: bicepAnalysis
    };

    console.log(
      "\nDetected Architecture\n"
    );

    console.dir(
      findings,
      {
        depth: null,
        colors: true
      }
    );

    // --------------------------------------------------
    // Build Normalized Architecture Model
    // --------------------------------------------------

    const architectureModel =
      buildArchitectureModel(findings);

    console.log(
      "\n==================================="
    );

    console.log(
      "Normalized Architecture Model"
    );

    console.log(
      "===================================\n"
    );

    console.dir(
      architectureModel,
      {
        depth: null,
        colors: true
      }
    );

    // --------------------------------------------------
    // Generate HLD from Architecture Model
    // --------------------------------------------------

    const hld =
      generateHLD(architectureModel);

    console.log(
      "\nGenerated HLD\n"
    );

    console.log(hld);

    // --------------------------------------------------
    // Generate Structurizr from Architecture Model
    // --------------------------------------------------

    const dsl =
      generateStructurizr(
        architectureModel
      );

    console.log(
      "\nStructurizr DSL\n"
    );

    console.log(dsl);

    // Save outputs
    saveReport(
      hld,
      dsl
    );

    console.log(
      "\nArchitectConnect analysis completed successfully."
    );
  } catch (error) {
    console.error(
      "\nArchitectConnect Error:",
      error.message
    );

    console.error(error.stack);
  }
}

runArchitectConnectLocal();

function buildArchitectureModel(findings) {
  return {
    application: {
      architecture:
        findings.architecture || "Unknown",

      frontend: {
        technology:
          findings.frontend?.[0] || "Unknown"
      },

      backend: {
        technology:
          findings.backend?.[0] || "Unknown",

        runtime:
          findings.runtime || "Unknown"
      },

      buildTool:
        findings.buildTool || "Unknown",

      tools:
        findings.tools || [],

      components:
        findings.components || []
    },

    containerization: {
      technology:
        findings.infrastructure?.docker?.detected
          ? "Docker"
          : "Not detected",

      baseImages:
        findings.infrastructure?.docker?.baseImages || [],

      exposedPorts:
        findings.infrastructure?.docker?.exposedPorts || [],

      commands:
        findings.infrastructure?.docker?.commands || [],

      workdir:
        findings.infrastructure?.docker?.workdir || "",

      entrypoint:
        findings.infrastructure?.docker?.entrypoint || ""
    },

    deployment: {
      technology:
        findings.infrastructure?.kubernetes?.detected
          ? "Kubernetes"
          : "Not detected",

      deployments:
        findings.infrastructure?.kubernetes?.deployments || [],

      services:
        findings.infrastructure?.kubernetes?.services || []
    },

    infrastructure: {
      terraform: {
        detected:
          findings.infrastructure?.terraform?.detected || false,

        providers:
          findings.infrastructure?.terraform?.providers || [],

        resources:
          findings.infrastructure?.terraform?.resources || []
      },

      bicep: {
        detected:
          findings.infrastructure?.bicep?.detected || false,

        resources:
          findings.infrastructure?.bicep?.resources || []
      }
    },

    assessment: {
      score:
        findings.architectureScore || 0,

      recommendations:
        findings.recommendations || []
    }
  };
}

module.exports = buildArchitectureModel;

