{
  "name": "architectconnect",
  "version": "1.0.0",
  "description": "ArchitectConnect POC",
  "main": "githubConnector.js",
  "scripts": {
    "start": "node githubConnector.js"
  },
  "dependencies": {
    "@github/copilot-sdk": "^1.0.16",
    "@modelcontextprotocol/sdk": "^1.30.0",
    "@octokit/rest": "^21.0.0",
    "dotenv": "^16.4.5",
    "zod": "^4.6.5"
  }
}

const fs =
  require("fs");

const path =
  require("path");

// ==================================================
// ARCHITECTCONNECT FINAL OUTPUT GENERATOR
// FR-AC-010
//
// Produces:
// - ArchitectureReport.md
// - architecture.dsl
//
// Validates:
// - Files were created
// - Files are non-empty
//
// Summarizes:
// - Applications
// - APIs
// - Components
// - Relationships
// - Infrastructure
// - Gaps
// - Assumptions
// - Architecture evidence score
// ==================================================

function saveReport(
  hld,
  dsl,
  findings = {},
  metadata = {}
) {
  // ==================================================
  // SAFETY
  // ==================================================

  const safeHld =
    typeof hld === "string"
      ? hld
      : "";

  const safeDsl =
    typeof dsl === "string"
      ? dsl
      : "";

  const safeFindings =
    findings &&
    typeof findings === "object"
      ? findings
      : {};

  const safeMetadata =
    metadata &&
    typeof metadata === "object"
      ? metadata
      : {};

  // ==================================================
  // OUTPUT FILES
  // ==================================================

  const reportFile =
    "ArchitectureReport.md";

  const diagramFile =
    "architecture.dsl";

  const reportPath =
    path.resolve(
      reportFile
    );

  const diagramPath =
    path.resolve(
      diagramFile
    );

  // ==================================================
  // VALIDATE CONTENT BEFORE WRITING
  // ==================================================

  if (!safeHld.trim()) {
    throw new Error(
      "ArchitectureReport.md cannot be generated because HLD content is empty."
    );
  }

  if (!safeDsl.trim()) {
    throw new Error(
      "architecture.dsl cannot be generated because Structurizr content is empty."
    );
  }

  // ==================================================
  // WRITE OUTPUT FILES
  // ==================================================

  fs.writeFileSync(
    reportPath,
    safeHld,
    "utf8"
  );

  fs.writeFileSync(
    diagramPath,
    safeDsl,
    "utf8"
  );

  // ==================================================
  // VALIDATE GENERATED FILES
  // ==================================================

  const reportExists =
    fs.existsSync(
      reportPath
    );

  const diagramExists =
    fs.existsSync(
      diagramPath
    );

  const reportSize =
    reportExists
      ? fs.statSync(
          reportPath
        ).size
      : 0;

  const diagramSize =
    diagramExists
      ? fs.statSync(
          diagramPath
        ).size
      : 0;

  const reportValid =
    reportExists &&
    reportSize > 0;

  const diagramValid =
    diagramExists &&
    diagramSize > 0;

  if (
    !reportValid ||
    !diagramValid
  ) {
    throw new Error(
      "ArchitectConnect final architecture output validation failed."
    );
  }

  // ==================================================
  // NORMALIZE FINAL ARCHITECTURE COUNTS
  // ==================================================

  const applications =
    Array.isArray(
      safeFindings.applications
    )
      ? safeFindings.applications
      : [];

  const apis =
    Array.isArray(
      safeFindings.apis
    )
      ? safeFindings.apis
      : [];

  const relationships =
    Array.isArray(
      safeFindings.relationships
    )
      ? safeFindings.relationships
      : [];

  const deployment =
    Array.isArray(
      safeFindings.deployment
    )
      ? safeFindings.deployment
      : [];

  const gaps =
    Array.isArray(
      safeFindings.gaps
    )
      ? safeFindings.gaps
      : [];

  const assumptions =
    Array.isArray(
      safeFindings.assumptions
    )
      ? safeFindings.assumptions
      : [];

  // ==================================================
  // DETAILED COMPONENT COUNT
  // ==================================================

  const nodeComponents =
    Array.isArray(
      safeFindings
        .nodeAnalysis
        ?.components
    )
      ? safeFindings
          .nodeAnalysis
          .components
      : [];

  const pythonComponents =
    Array.isArray(
      safeFindings
        .pythonApplicationAnalysis
        ?.components
    )
      ? safeFindings
          .pythonApplicationAnalysis
          .components
      : [];

  const componentCount =
    nodeComponents.length +
    pythonComponents.length;

  // ==================================================
  // METADATA
  // ==================================================

  const repository =
    safeMetadata.repository ||
    safeMetadata.repositoryName ||
    "Not provided";

  const branch =
    safeMetadata.branch ||
    "Not provided";

  const architecture =
    safeFindings.architecture ||
    "Not detected";

  const architectureScore =
    typeof safeFindings.architectureScore ===
    "number"
      ? safeFindings.architectureScore
      : 0;

  // ==================================================
  // FINAL ARCHITECTURE OUTPUT SUMMARY
  // ==================================================

  console.log(
    "\n========== FINAL ARCHITECTURE OUTPUT =========="
  );

  console.log(
    "\nRepository:"
  );

  console.log(
    repository
  );

  console.log(
    "\nBranch:"
  );

  console.log(
    branch
  );

  console.log(
    "\nArchitecture:"
  );

  console.log(
    architecture
  );

  console.log(
    "\nArchitecture Summary:"
  );

  console.log(
    `- Applications: ${applications.length}`
  );

  console.log(
    `- APIs: ${apis.length}`
  );

  console.log(
    `- Detailed Components: ${componentCount}`
  );

  console.log(
    `- Relationships: ${relationships.length}`
  );

  console.log(
    `- Infrastructure Technologies: ${deployment.length}`
  );

  console.log(
    `- Architecture Gaps: ${gaps.length}`
  );

  console.log(
    `- Assumptions Requiring Validation: ${assumptions.length}`
  );

  console.log(
    "\nArchitecture Evidence Score:"
  );

  console.log(
    `${architectureScore}/100`
  );

  // ==================================================
  // GENERATED OUTPUTS
  // ==================================================

  console.log(
    "\nGenerated Outputs:"
  );

  console.log(
    `[OK] ${reportFile} (${reportSize} bytes)`
  );

  console.log(
    `[OK] ${diagramFile} (${diagramSize} bytes)`
  );

  // ==================================================
  // VALIDATION SUMMARY
  // ==================================================

  console.log(
    "\nArchitect Validation:"
  );

  if (
    gaps.length === 0 &&
    assumptions.length === 0
  ) {
    console.log(
      "- No architecture validation items identified."
    );
  } else {
    console.log(
      `- ${gaps.length} architecture gap(s) require review.`
    );

    console.log(
      `- ${assumptions.length} architecture assumption(s) require review.`
    );
  }

  console.log(
    "\nStatus:"
  );

  console.log(
    "Architecture output generation complete."
  );

  console.log(
    "\n===============================================\n"
  );

  // ==================================================
  // RETURN OUTPUT METADATA
  // ==================================================

  return {
    success:
      true,

    files: [
      {
        name:
          reportFile,

        path:
          reportPath,

        size:
          reportSize,

        type:
          "hld"
      },

      {
        name:
          diagramFile,

        path:
          diagramPath,

        size:
          diagramSize,

        type:
          "architecture_diagram"
      }
    ],

    summary: {
      repository,
      branch,
      architecture,

      applications:
        applications.length,

      apis:
        apis.length,

      components:
        componentCount,

      relationships:
        relationships.length,

      infrastructureTechnologies:
        deployment.length,

      gaps:
        gaps.length,

      assumptions:
        assumptions.length,

      architectureEvidenceScore:
        architectureScore
    }
  };
}

module.exports =
  saveReport;

const analyzeNode =
  require("./analyzers/node/nodeAnalyzer");

const analyzePythonApplication =
  require("./analyzers/python/pythonAnalyzer");

const analyzeGaps =
  require("./analyzers/gapsAnalyzer");

function scanRepository(
  contents,
  packageContent = ""
) {
  // ==================================================
  // ARCHITECTURE FINDINGS
  // ==================================================

  const findings = {
    frontend: [],
    backend: [],

    languages: [],
    frameworks: [],

    // FR-AC-003
    applications: [],
    apis: [],

    nodeAnalysis: null,
    pythonApplicationAnalysis: null,

    // FR-AC-005
    relationships: [],

    // FR-AC-009
    gaps: [],
    assumptions: [],

    deployment: [],
    deploymentArchitecture: [],

    tools: [],

    architecture: "",

    runtime: "",
    buildTool: "",

    runtimes: [],
    buildTools: [],

    components: [],

    python: {
      detected: false,
      confidence: 0,
      sourceFiles: [],
      dependencyFiles: [],
      frameworks: [],
      evidence: []
    },

    recommendations: [],
    architectureScore: 0
  };

  // ==================================================
  // SAFETY / NORMALIZATION
  // ==================================================

  if (!Array.isArray(contents)) {
    contents = [];
  }

  if (
    typeof packageContent !== "string"
  ) {
    packageContent = "";
  }

  const normalizedPackageContent =
    packageContent.toLowerCase();

  // ==================================================
  // REPOSITORY FILE INFORMATION
  // ==================================================

  const fileNames =
    contents.map((item) =>
      String(
        item.name || ""
      )
        .replace(/\\/g, "/")
        .toLowerCase()
    );

