  }

  if (
    findings.tools.includes(
      "TypeScript"
    )
  ) {
    addRecommendation(
      "Enable strict TypeScript type checking."
    );
  }

  if (
    findings.python.detected
  ) {
    addRecommendation(
      "Maintain clear module boundaries within the Python application."
    );
  }

  if (
    findings.python.frameworks.includes(
      "FastAPI"
    )
  ) {
    addRecommendation(
      "Organize FastAPI endpoints using routers and maintain clear API, service, and data-access boundaries."
    );
  }

  if (
    findings.python.frameworks.includes(
      "Django"
    )
  ) {
    addRecommendation(
      "Maintain clear Django application boundaries and separate business logic from views."
    );
  }

  if (
    findings.python.frameworks.includes(
      "Flask"
    )
  ) {
    addRecommendation(
      "Consider Flask Blueprints for modular application organization."
    );
  }

  if (
    findings.deployment.includes(
      "Docker"
    )
  ) {
    addRecommendation(
      "Consider multi-stage Docker builds and container image scanning."
    );
  }

  if (
    findings.deployment.includes(
      "Terraform"
    )
  ) {
    addRecommendation(
      "Consider reusable Terraform modules and remote state management."
    );
  }

  if (
    findings.deployment.includes(
      "Bicep"
    )
  ) {
    addRecommendation(
      "Consider organizing Bicep resources into reusable modules."
    );
  }

  if (
    findings.deployment.includes(
      "Kubernetes"
    )
  ) {
    addRecommendation(
      "Consider Kubernetes health probes, resource limits, and deployment policies."
    );
  }

  // ==================================================
  // FR-AC-009:
  // GAP & ASSUMPTION ANALYSIS
  // ==================================================
  //
  // IMPORTANT:
  //
  // Run this after application, component,
  // relationship, technology and infrastructure
  // analysis so the analyzer receives completed
  // repository findings.
  // ==================================================

  const gapAnalysis =
    analyzeGaps(
      findings
    );

  findings.gaps =
    gapAnalysis &&
    Array.isArray(
      gapAnalysis.gaps
    )
      ? gapAnalysis.gaps
      : [];

  findings.assumptions =
    gapAnalysis &&
    Array.isArray(
      gapAnalysis.assumptions
    )
      ? gapAnalysis.assumptions
      : [];

  // ==================================================
  // DEBUG: PYTHON SOURCE
  // ==================================================

  const firstPythonFile =
    contents.find((item) =>
      String(
        item.path ||
        item.name ||
        ""
      )
        .replace(/\\/g, "/")
        .toLowerCase()
        .endsWith(".py")
    );

  console.log(
    "\n========== PYTHON FILE CHECK =========="
  );

  if (firstPythonFile) {
    console.log(
      "Python file:",
      firstPythonFile.path ||
      firstPythonFile.name
    );

    const source =
      getFileContent(
        firstPythonFile
      );

    console.log(
      "Source content available:",
      source.length > 0
        ? "YES"
        : "NO"
    );

    if (
      source.length > 0
    ) {
      console.log(
        "Source length:",
        source.length
      );
    }
  } else {
    console.log(
      "No Python source file found."
    );
  }

  console.log(
    "=======================================\n"
  );

  // ==================================================
  // DEBUG: PYTHON TECHNOLOGY ANALYSIS
  // ==================================================

  console.log(
    "\n========== PYTHON ANALYSIS =========="
  );

  console.log(
    JSON.stringify(
      findings.python,
      null,
      2
    )
  );

  console.log(
    "=====================================\n"
  );

  // ==================================================
  // DEBUG: NODE APPLICATION
  // ==================================================

  console.log(
    "\n========== NODE APPLICATION ANALYSIS =========="
  );

  console.log(
    JSON.stringify(
      findings.nodeAnalysis,
      null,
      2
    )
  );

  console.log(
    "===============================================\n"
  );

  // ==================================================
  // DEBUG: PYTHON APPLICATION
  // ==================================================

  console.log(
    "\n========== PYTHON APPLICATION ANALYSIS =========="
  );

  console.log(
    JSON.stringify(
      findings.pythonApplicationAnalysis,
      null,
      2
    )
  );

  console.log(
    "=================================================\n"
  );

  // ==================================================
  // COMBINED REPOSITORY ANALYSIS
  // ==================================================

  console.log(
    "\n========== REPOSITORY ANALYSIS =========="
  );

  // ==================================================
  // APPLICATIONS
  // ==================================================

  console.log(
    "\nApplications:"
  );

  if (
    findings.applications.length === 0
  ) {
    console.log(
      "- No applications detected"
    );
  } else {
    for (
      const application of
      findings.applications
    ) {
      console.log(
        `- ${application.name}`
      );

      console.log(
        `  Language: ${
          application.language ||
          "Not detected"
        }`
      );

      console.log(
        `  Runtime: ${
          application.runtime ||
          "Not detected"
        }`
      );

      console.log(
        `  Framework: ${
          application.framework ||
          "Not detected"
        }`
      );

      if (
        Array.isArray(
          application.sourceFiles
        ) &&
        application.sourceFiles.length > 0
      ) {
        console.log(
          "  Source files:"
        );

        for (
          const sourceFile of
          application.sourceFiles
        ) {
          console.log(
            `    - ${sourceFile}`
          );
        }
      }
    }
  }

  // ==================================================
  // APIs
  // ==================================================

  console.log(
    "\nAPIs:"
  );

  if (
    findings.apis.length === 0
  ) {
    console.log(
      "- No application APIs detected"
    );
  } else {
    for (
      const api of
      findings.apis
    ) {
      console.log(
        `- ${api.application}: ${api.method} ${api.path}`
      );

      console.log(
        `  Framework: ${
          api.framework ||
          "Not detected"
        }`
      );

      if (api.handler) {
        console.log(
          `  Handler: ${api.handler}`
        );
      }

      console.log(
        `  Source: ${
          api.source ||
          "Unknown"
        }`
      );
    }
  }

  // ==================================================
  // FR-AC-005:
  // RELATIONSHIPS
  // ==================================================

  console.log(
    "\nRelationships:"
  );

  if (
    findings.relationships.length === 0
  ) {
    console.log(
      "- No application relationships detected"
    );
  } else {
    for (
      const relationship of
      findings.relationships
    ) {
      console.log(
        `- ${relationship.from} -> ${relationship.to}`
      );

      console.log(
        `  Relationship: ${
          relationship.relationship ||
          "depends_on"
        }`
      );

      console.log(
        `  Application: ${
          relationship.application ||
          "Unknown"
        }`
      );

      if (
        relationship.evidence
      ) {
        console.log(
          `  Evidence: ${relationship.evidence}`
        );
      }

      if (
        relationship.source
      ) {
        console.log(
          `  Source: ${relationship.source}`
        );
      }

      if (
        relationship.line
      ) {
        console.log(
          `  Line: ${relationship.line}`
        );
      }
    }
  }

  // ==================================================
  // COMPONENTS
  // ==================================================

  console.log(
    "\nComponents:"
  );

  if (
    findings.components.length === 0
  ) {
    console.log(
      "- No components detected"
    );
  } else {
    for (
      const component of
      findings.components
    ) {
      console.log(
        `- ${component}`
      );
    }
  }

  // ==================================================
  // INFRASTRUCTURE
  // ==================================================

  console.log(
    "\nInfrastructure:"
  );

  if (
    findings.deployment.length === 0
  ) {
    console.log(
      "- No infrastructure technologies detected"
    );
  } else {
    for (
      const technology of
      findings.deployment
    ) {
      console.log(
        `- ${technology}`
      );
    }
  }

  // ==================================================
  // TECHNOLOGY STACK
  // ==================================================

  console.log(
    "\nLanguages:"
  );

  for (
    const language of
    findings.languages
  ) {
    console.log(
      `- ${language}`
    );
  }

  console.log(
    "\nFrameworks:"
  );

  for (
    const framework of
    findings.frameworks
  ) {
    console.log(
      `- ${framework}`
    );
  }

  console.log(
    "\nRuntimes:"
  );

  for (
    const runtime of
    findings.runtimes
  ) {
    console.log(
      `- ${runtime}`
    );
  }

  console.log(
    "\nArchitecture:"
  );

  console.log(
    findings.architecture ||
    "Not detected"
  );

  console.log(
    "\nArchitecture Score:"
  );

  console.log(
    `${findings.architectureScore}/100`
  );

  console.log(
    "\n=========================================\n"
  );

  // ==================================================
  // FR-AC-009:
  // GAPS & ASSUMPTIONS OUTPUT
  // ==================================================

  console.log(
    "\n========== GAPS & ASSUMPTIONS =========="
  );

  // --------------------------------------------------
  // GAPS
  // --------------------------------------------------

  console.log(
    "\nGaps:"
  );

  if (
    findings.gaps.length === 0
  ) {
    console.log(
      "- No architecture gaps identified"
    );
  } else {
    for (
      const gap of
      findings.gaps
    ) {
      console.log(
        `- ${gap.area}`
      );

      console.log(
        `  Status: ${
          gap.status
        }`
      );

      console.log(
        `  Reason: ${
          gap.reason
        }`
      );

      console.log(
        `  Validation Required: ${
          gap.requiresValidation
            ? "Yes"
            : "No"
        }`
      );
    }
  }

  // --------------------------------------------------
  // ASSUMPTIONS
  // --------------------------------------------------

  console.log(
    "\nAssumptions:"
  );

  if (
    findings.assumptions.length === 0
  ) {
    console.log(
      "- No architecture assumptions identified"
    );
  } else {
    for (
      const assumption of
      findings.assumptions
    ) {
      console.log(
        `- ${assumption.area}`
      );

      console.log(
        `  Status: ${
          assumption.status
        }`
      );

      console.log(
        `  Assumption: ${
          assumption.assumption
        }`
      );

      console.log(
        `  Reason: ${
          assumption.reason
        }`
      );

      console.log(
        `  Validation Required: ${
          assumption.requiresValidation
            ? "Yes"
            : "No"
        }`
      );
    }
  }

  console.log(
    "\n===========================================\n"
  );

  // ==================================================
  // RETURN FINDINGS
  // ==================================================

  return findings;
}

module.exports =
  scanRepository;

const discoverApplications =
  require(
    "./analyzers/discovery/applicationDiscovery"
  );
const analyzeNode =
  require("./analyzers/node/nodeAnalyzer");

const analyzePythonApplication =
  require("./analyzers/python/pythonAnalyzer");

const analyzeGaps =
  require("./analyzers/gapsAnalyzer");

const analyzeJavaScriptImports =
require(
"./analyzers/dependencies/javascriptImportAnalyzer"
);

const analyzePythonImports =
require(
"./analyzers/dependencies/pythonImportAnalyzer"
);

const discoverComponents =
require(
"./analyzers/discovery/componentDiscovery"
);

function scanRepository(
  contents,
  packageContent = ""
) {
  // ==================================================
  // ARCHITECTURE FINDINGS
  // ==================================================

const findings = {
  frontend: [],
  backend: [],

  languages: [],
  frameworks: [],

  applications: [],
  // Dynamic application discovery.
// Kept separate from the existing application model
// while the new discovery engine is validated.
discoveredApplications: [],

  apis: [],
  discoveredComponents: [],
discoveredRelationships: [],

  nodeAnalysis: null,
  pythonApplicationAnalysis: null,

  relationships: [],

  gaps: [],
  assumptions: [],

  deployment: [],
  deploymentArchitecture: [],

  tools: [],

  architecture: "",

  runtime: "",
  buildTool: "",

  runtimes: [],
  buildTools: [],

  components: [],

  python: {
    detected: false,
    confidence: 0,
    sourceFiles: [],
    dependencyFiles: [],
    frameworks: [],
    evidence: []
  },

  recommendations: [],
  architectureScore: 0
};

  // ==================================================
  // SAFETY / NORMALIZATION
  // ==================================================

  if (!Array.isArray(contents)) {
    contents = [];
  }

  if (
    typeof packageContent !== "string"
  ) {
    packageContent = "";
  }

  const normalizedPackageContent =
    packageContent.toLowerCase();

  // ==================================================
  // REPOSITORY FILE INFORMATION
  // ==================================================

  const fileNames =
    contents.map((item) =>
      String(
        item.name || ""
      )
        .replace(/\\/g, "/")
        .toLowerCase()
    );

  const filePaths =
    contents.map((item) =>
      String(
        item.path ||
        item.name ||
        ""
      )
        .replace(/\\/g, "/")
        .toLowerCase()
    );

  // ==================================================
  // DEBUG: REPOSITORY FILES
  // ==================================================

  console.log(
    "\n========== REPOSITORY FILES =========="
  );

  contents.forEach((item) => {
    console.log(
      item.path ||
      item.name
    );
  });

  console.log(
    "======================================\n"
  );

  // ==================================================
  // HELPERS
  // ==================================================

  // --------------------------------------------------
  // ADD UNIQUE VALUE
  // --------------------------------------------------

  function addUnique(
    array,
    value
  ) {
    if (
      value &&
      !array.includes(value)
    ) {
      array.push(value);
    }
  }


  // --------------------------------------------------
  // ADD RECOMMENDATION
  // --------------------------------------------------

  function addRecommendation(
    value
  ) {
    addUnique(
      findings.recommendations,
      value
    );
  }


  // --------------------------------------------------
  // GET FILE CONTENT
  // --------------------------------------------------

  function getFileContent(
    item
  ) {
    if (!item) {
      return "";
    }

    if (
      typeof item.content === "string"
    ) {
      return item.content;
    }

    if (
      typeof item.text === "string"
    ) {
      return item.text;
    }

    return "";
  }


  // --------------------------------------------------
  // CHECK PATH SEGMENT
  // --------------------------------------------------
  //
  // This avoids depending on a fixed parent directory.
  //
  // Examples:
  //
  // applications/backend/src/server.js
  // packages/backend/src/server.js
  // apps/backend/src/server.js
  // services/backend/src/server.js
  //
  // containsPathSegment(path, "backend")
  // returns true for all of the examples above.
  //
  // --------------------------------------------------

  function containsPathSegment(
    filePath,
    segment
  ) {
    const normalizedPath =
      `/${
        String(
          filePath || ""
        )
          .replace(
            /\\/g,
            "/"
          )
          .replace(
            /^\/+|\/+$/g,
            ""
          )
          .toLowerCase()
      }/`;

    const normalizedSegment =
      `/${
        String(
          segment || ""
        )
          .replace(
            /\\/g,
            "/"
          )
          .replace(
            /^\/+|\/+$/g,
            ""
          )
          .toLowerCase()
      }/`;

    return normalizedPath.includes(
      normalizedSegment
    );
  }
  


  // ==================================================
  // FR-AC-003:
  // APPLICATION ANALYSIS
  // ==================================================
  // ==================================================
// DYNAMIC APPLICATION DISCOVERY
// ==================================================

const discoveredApplications =
  discoverApplications(
    contents
  );

findings.discoveredApplications =
  Array.isArray(
    discoveredApplications
  )
    ? discoveredApplications
    : [];
    // ==================================================
  // DYNAMIC COMPONENT & RELATIONSHIP DISCOVERY
  // ==================================================
  //
  // Purpose:
  //
  // Analyze each dynamically discovered application
  // independently.
  //
  // JavaScript / TypeScript applications:
  //   -> JavaScript import graph
  //
  // Python applications:
  //   -> Python import graph
  //
  // The resulting import graph is then used by
  // componentDiscovery to infer architectural
  // components.
  //
  // IMPORTANT:
  //
  // These results are stored separately from the
  // existing production components and relationships.
  //
  // Existing:
  //
  // findings.components
  // findings.relationships
  //
  // Dynamic:
  //
  // findings.discoveredComponents
  // findings.discoveredRelationships
  //
  // ==================================================


  const discoveredComponents = [];

  const discoveredRelationships = [];


  // ==================================================
  // PROCESS EACH DISCOVERED APPLICATION
  // ==================================================

  for (
    const application of
    findings.discoveredApplications
  ) {

    // ==================================================
    // APPLICATION VALIDATION
    // ==================================================

    if (
      !application ||
      !application.root
    ) {
      continue;
    }


    // ==================================================
    // NORMALIZE APPLICATION ROOT
    // ==================================================

    const applicationRoot =
      String(
        application.root ||
        ""
      )
        .replace(
          /\\/g,
          "/"
        )
        .replace(
          /^\/+|\/+$/g,
          ""
        );


    if (!applicationRoot) {
      continue;
    }


    // ==================================================
    // SELECT APPLICATION FILES
    // ==================================================
    //
    // Example:
    //
    // application.root:
    //
    // applications/backend
    //
    // Selected:
    //
    // applications/backend/package.json
    // applications/backend/src/server.js
    // applications/backend/src/...
    //
    // Other application files are excluded.
    //
    // ==================================================

    const applicationFiles =
      contents.filter(
        (item) => {

          if (!item) {
            return false;
          }


          const filePath =
            String(
              item.path ||
              item.name ||
              ""
            )
              .replace(
                /\\/g,
                "/"
              )
              .replace(
                /^\/+|\/+$/g,
                ""
              );


          if (!filePath) {
            return false;
          }


          return (
            filePath ===
              applicationRoot ||
            filePath.startsWith(
              `${applicationRoot}/`
            )
          );
        }
      );


    // ==================================================
    // NO APPLICATION FILES
    // ==================================================

    if (
      applicationFiles.length ===
      0
    ) {
      continue;
    }


    // ==================================================
    // APPLICATION DEPENDENCY GRAPH
    // ==================================================

    let applicationRelationships =
      [];


    // ==================================================
    // NODE.JS / JAVASCRIPT / TYPESCRIPT
    // ==================================================
    //
    // Examples:
    //
    // Express
    // React
    // generic Node.js applications
    //
    // ==================================================

    if (
      application.runtime ===
      "Node.js"
    ) {

      const javascriptRelationships =
        analyzeJavaScriptImports(
          applicationFiles
        );


      if (
        Array.isArray(
          javascriptRelationships
        )
      ) {
        applicationRelationships =
          javascriptRelationships;
      }
    }


    // ==================================================
    // PYTHON
    // ==================================================
    //
    // Examples:
    //
    // FastAPI
    // Flask
    // Django
    // generic Python applications
    //
    // ==================================================

    if (
      application.runtime ===
      "Python"
    ) {

      const pythonRelationships =
        analyzePythonImports(
          applicationFiles,
          applicationRoot
        );


      if (
        Array.isArray(
          pythonRelationships
        )
      ) {
        applicationRelationships =
          pythonRelationships;
      }
    }


    // ==================================================
    // ENRICH RELATIONSHIPS WITH APPLICATION CONTEXT
    // ==================================================

    const enrichedRelationships =
      applicationRelationships.map(
        (relationship) => ({
          ...relationship,

          applicationId:
            application.id ||
            null,

          applicationRoot:
            applicationRoot,

          applicationType:
            application.type ||
            null,

          framework:
            application.framework ||
            null,

          runtime:
            application.runtime ||
            null,

          language:
            application.language ||
            null
        })
      );


    // ==================================================
    // STORE DYNAMIC RELATIONSHIPS
    // ==================================================

    discoveredRelationships.push(
      ...enrichedRelationships
    );


    // ==================================================
    // COMPONENT DISCOVERY
    // ==================================================
    //
    // Uses:
    //
    // application files
    // +
    // actual source dependency graph
    // +
    // application evidence
    //
    // to infer component roles.
    //
    // ==================================================

    const applicationComponents =
      discoverComponents({
        files:
          applicationFiles,

        relationships:
          enrichedRelationships,

        application
      });


    // ==================================================
    // ENRICH COMPONENTS
    // ==================================================

    const enrichedComponents =
      Array.isArray(
        applicationComponents
      )
        ? applicationComponents.map(
            (component) => ({
              ...component,

              applicationId:
                component.applicationId ||
                application.id ||
                null,

              applicationRoot:
                component.applicationRoot ||
                applicationRoot,

              applicationType:
                application.type ||
                null,

              framework:
                application.framework ||
                null,

              runtime:
                application.runtime ||
                null,

              language:
                application.language ||
                null
            })
          )
        : [];


    // ==================================================
    // STORE DYNAMIC COMPONENTS
    // ==================================================

    discoveredComponents.push(
      ...enrichedComponents
    );
  }


  // ==================================================
  // REMOVE DUPLICATE DYNAMIC RELATIONSHIPS
  // ==================================================

  const uniqueDiscoveredRelationships =
    [];

  const seenRelationships =
    new Set();


  for (
    const relationship of
    discoveredRelationships
  ) {

    const key =
      [
        relationship.applicationId,
        relationship.from,
        relationship.to ||
          relationship.importPath ||
          relationship.module,
        relationship.relationship
      ].join("|");


    if (
      seenRelationships.has(
        key
      )
    ) {
      continue;
    }


    seenRelationships.add(
      key
    );


    uniqueDiscoveredRelationships.push(
      relationship
    );
  }


  // ==================================================
  // REMOVE DUPLICATE DYNAMIC COMPONENTS
  // ==================================================

  const uniqueDiscoveredComponents =
    [];

  const seenComponents =
    new Set();


  for (
    const component of
    discoveredComponents
  ) {

    const key =
      [
        component.applicationId,
        component.source,
        component.role
      ].join("|");


    if (
      seenComponents.has(
        key
      )
    ) {
      continue;
    }


    seenComponents.add(
      key
    );


    uniqueDiscoveredComponents.push(
      component
    );
  }


  // ==================================================
  // STORE DYNAMIC RESULTS
  // ==================================================

  findings.discoveredComponents =
    uniqueDiscoveredComponents;


  findings.discoveredRelationships =
    uniqueDiscoveredRelationships;


  // ==================================================
  // DEBUG: DYNAMIC COMPONENTS
  // ==================================================

  console.log(
    "\n========== DISCOVERED COMPONENTS =========="
  );


  console.log(
    JSON.stringify(
      findings.discoveredComponents,
      null,
      2
    )
  );


  console.log(
    "===========================================\n"
  );


  // ==================================================
  // DEBUG: DYNAMIC RELATIONSHIPS
  // ==================================================

  console.log(
    "\n========== DISCOVERED RELATIONSHIPS =========="
  );


  console.log(
    JSON.stringify(
      findings.discoveredRelationships,
      null,
      2
    )
  );


  console.log(
    "==============================================\n"
  );


  // ==================================================
  // DEBUG: DYNAMIC DISCOVERY SUMMARY
  // ==================================================

  console.log(
