function scanRepository(
  contents,
  packageContent = ""
) {
  // ==================================================
  // ARCHITECTURE FINDINGS
  // ==================================================

const findings = {
  frontend: [],
  backend: [],

  languages: [],
  frameworks: [],

  applications: [],

discoveredApplications: [],


discoveredApis: [],

discoveredComponents: [],

discoveredRelationships: [],


architectureProjection:
  null,
selectedArchitecture:
null,

apis: [],


  nodeAnalysis: null,
  pythonApplicationAnalysis: null,

  relationships: [],

  gaps: [],
  assumptions: [],

  deployment: [],
  deploymentArchitecture: [],

  tools: [],

  architecture: "",

  runtime: "",
  buildTool: "",

  runtimes: [],
  buildTools: [],

  components: [],

  python: {
    detected: false,
    confidence: 0,
    sourceFiles: [],
    dependencyFiles: [],
    frameworks: [],
    evidence: []
  },

  recommendations: [],
  architectureScore: 0
};

  // ==================================================
  // SAFETY / NORMALIZATION
  // ==================================================

  if (!Array.isArray(contents)) {
    contents = [];
  }

  if (
    typeof packageContent !== "string"
  ) {
    packageContent = "";
  }

  const normalizedPackageContent =
    packageContent.toLowerCase();

  // ==================================================
  // REPOSITORY FILE INFORMATION
  // ==================================================

  const fileNames =
    contents.map((item) =>
      String(
        item.name || ""
      )
        .replace(/\\/g, "/")
        .toLowerCase()
    );

  const filePaths =
    contents.map((item) =>
      String(
        item.path ||
        item.name ||
        ""
      )
        .replace(/\\/g, "/")
        .toLowerCase()
    );

  // ==================================================
  // DEBUG: REPOSITORY FILES
  // ==================================================

