  );

  // ==================================================
  // HELPERS
  // ==================================================

  // --------------------------------------------------
  // ADD UNIQUE VALUE
  // --------------------------------------------------

  function addUnique(
    array,
    value
  ) {
    if (
      value &&
      !array.includes(value)
    ) {
      array.push(value);
    }
  }


  // --------------------------------------------------
  // ADD RECOMMENDATION
  // --------------------------------------------------

  function addRecommendation(
    value
  ) {
    addUnique(
      findings.recommendations,
