// ==================================================
// GITHUB CLIENT
// ==================================================

function createGitHubClient() {
  if (!process.env.GITHUB_TOKEN) {
    throw new Error(
      "GITHUB_TOKEN is missing from the ArchitectConnect .env file."
    );
  }

  return new Octokit({
    auth: process.env.GITHUB_TOKEN
  });
}


// ==================================================
// ARCHITECTURE FILE FILTER
// ==================================================

function shouldLoadContent(
  filePath
) {
  const normalizedPath =
    String(filePath || "")
      .replace(/\\/g, "/")
      .toLowerCase();

  return (
    normalizedPath.endsWith("package.json") ||
    normalizedPath.endsWith("yarn.lock") ||

    normalizedPath.endsWith(".js") ||
    normalizedPath.endsWith(".jsx") ||
    normalizedPath.endsWith(".ts") ||
    normalizedPath.endsWith(".tsx") ||
    normalizedPath.endsWith(".mjs") ||
    normalizedPath.endsWith(".cjs") ||

    normalizedPath.endsWith(".py") ||

    normalizedPath.endsWith("requirements.txt") ||
    normalizedPath.endsWith("pyproject.toml") ||
    normalizedPath.endsWith("pipfile") ||
    normalizedPath.endsWith("pipfile.lock") ||
    normalizedPath.endsWith("poetry.lock") ||
    normalizedPath.endsWith("uv.lock") ||
    normalizedPath.endsWith("setup.py") ||
    normalizedPath.endsWith("setup.cfg") ||

    normalizedPath === "dockerfile" ||
    normalizedPath.endsWith("/dockerfile") ||
    normalizedPath.endsWith(".dockerfile") ||

    normalizedPath.endsWith(".tf") ||
    normalizedPath.endsWith(".tfvars") ||

    normalizedPath.endsWith(".bicep") ||

    normalizedPath.endsWith(".yaml") ||
    normalizedPath.endsWith(".yml")
  );
}


// ==================================================
// ANALYZE ALREADY-LOADED REPOSITORY CONTENT
// ==================================================

function analyzeRepositoryContents(
  contents,
  packageContent = "",
  metadata = {}
) {
  // ==================================================
  // REPOSITORY SCAN
  // ==================================================

  const findings =
    scanRepository(
      contents,
      packageContent
    );


  // ==================================================
  // SELECTED ARCHITECTURE FOR HLD
  // ==================================================
  //
  // Prefer the architecture selected by the dynamic
  // architecture selector.
  //
  // If no selected architecture is available, retain
  // the existing architecture model as a fallback.
  //
  // ==================================================

  const selectedArchitecture =
    findings &&
    findings.selectedArchitecture &&
    findings.selectedArchitecture.architecture
      ? findings.selectedArchitecture.architecture
      : {
          applications:
            findings.applications,

          apis:
            findings.apis,

          components:
            findings.components,

          relationships:
            findings.relationships
        };


  // ==================================================
  // HLD FINDINGS
  // ==================================================
  //
  // Preserve repository-level findings:
  //
  // - languages
  // - frameworks
  // - runtimes
  // - deployment
  // - infrastructure
  // - gaps
  // - assumptions
  // - recommendations
  // - architecture score
  //
  // Replace only:
  //
  // - applications
  // - APIs
  // - components
  // - relationships
  //
  // with the selected architecture model.
  //
  // ==================================================

  const hldFindings = {
    ...findings,

    applications:
      Array.isArray(
        selectedArchitecture.applications
      )
        ? selectedArchitecture.applications
        : findings.applications,

    apis:
      Array.isArray(
        selectedArchitecture.apis
      )
        ? selectedArchitecture.apis
        : findings.apis,

    components:
      Array.isArray(
        selectedArchitecture.components
      )
        ? selectedArchitecture.components
        : findings.components,

    relationships:
      Array.isArray(
        selectedArchitecture.relationships
      )
        ? selectedArchitecture.relationships
        : findings.relationships
  };


  // ==================================================
  // DEBUG: HLD ARCHITECTURE INPUT
  // ==================================================

  console.log(
    "\n========== HLD ARCHITECTURE INPUT =========="
  );

  console.log(
    "Selected source:",
    findings &&
    findings.selectedArchitecture
      ? findings.selectedArchitecture.source
      : "legacy"
  );

  console.log(
    "Applications:",
    Array.isArray(
      hldFindings.applications
    )
      ? hldFindings.applications.length
      : 0
  );

  console.log(
    "APIs:",
    Array.isArray(
      hldFindings.apis
    )
      ? hldFindings.apis.length
      : 0
  );

  console.log(
    "Components:",
    Array.isArray(
      hldFindings.components
    )
      ? hldFindings.components.length
      : 0
  );

  console.log(
    "Relationships:",
    Array.isArray(
      hldFindings.relationships
    )
      ? hldFindings.relationships.length
      : 0
  );

  console.log(
    "============================================\n"
  );


  // ==================================================
  // GENERATE HLD FROM SELECTED ARCHITECTURE
  // ==================================================

  const hld =
    generateHLD(
      hldFindings
    );


  // ==================================================
  // GENERATE STRUCTURIZR
  // ==================================================
  //
  // IMPORTANT:
  //
  // Structurizr remains on the existing findings
  // model for this checkpoint.
  //
  // Dynamic Structurizr migration will happen only
  // after the HLD output has been validated.
  //
  // ==================================================

  const dsl =
  generateStructurizr(
    hldFindings
  );
  // ==================================================
// GENERATE PROPOSED ADRs
// ==================================================

const adrs =
  generateADRs(
    hldFindings,
    metadata
  );
  console.log(
  "\n========== DSL ARCHITECTURE INPUT =========="
);

console.log(
  "Selected source:",
  findings.selectedArchitecture
    ? findings.selectedArchitecture.source
    : "legacy"
);

console.log(
  "Applications:",
  hldFindings.applications.length
);

console.log(
  "APIs:",
  hldFindings.apis.length
);

console.log(
  "Components:",
  hldFindings.components.length
);

console.log(
  "Relationships:",
  hldFindings.relationships.length
);

console.log(
  "============================================\n"
);


  // ==================================================
  // RESULT
  // ==================================================

  return {
  repository:
    metadata.repository ||
    null,

  branch:
    metadata.branch ||
    null,

  treeSha:
    metadata.treeSha ||
    null,

  findings,

  hld,

  dsl,

  adrs
};
}


// ==================================================
// LOAD ONE GITHUB BLOB
// ==================================================

async function loadBlobContent(
  octokit,
  owner,
  repo,
  sha
) {
  const response =
    await octokit.git.getBlob({
      owner,
      repo,
      file_sha: sha
    });

  if (!response.data.content) {
    return "";
  }

  const encoding =
    response.data.encoding ||
    "base64";

  return Buffer.from(
    response.data.content,
    encoding
  ).toString("utf8");
}

