      provider:
        loaded.provider,

      repositoryUrl,

      repository:
        loaded.repository.fullName,

      branch:
        loaded.ref
    }
  };
}

// ==================================================
// ANALYZE GITHUB REPOSITORY
// ==================================================

async function analyzeGitHubRepository(
  owner,
  repo
) {
  if (!owner || !repo) {
    throw new Error(
      "Both GitHub repository owner and repository name are required."
    );
  }


  const octokit =
    createGitHubClient();


  // --------------------------------------------------
  // Repository metadata
  // --------------------------------------------------

  const repositoryResponse =
    await octokit.repos.get({
      owner,
      repo
    });

  const defaultBranch =
    repositoryResponse
      .data
      .default_branch;

  if (!defaultBranch) {
    throw new Error(
      "GitHub repository has no default branch."
    );
  }


  // --------------------------------------------------
  // Branch
  // --------------------------------------------------

  const branchResponse =
    await octokit.repos.getBranch({
      owner,
      repo,
      branch: defaultBranch
    });

  const treeSha =
    branchResponse
      .data
      .commit
      .commit
      .tree
      .sha;


  // --------------------------------------------------
  // Repository tree
  // --------------------------------------------------

  const treeResponse =
    await octokit.git.getTree({
      owner,
      repo,
      tree_sha: treeSha,
      recursive: "true"
    });

  if (treeResponse.data.truncated) {
    console.warn(
      "WARNING: GitHub returned a truncated repository tree."
    );
  }


  const repositoryFiles =
    (
      treeResponse.data.tree ||
      []
    ).filter(
      (item) =>
        item.type === "blob"
    );


  // --------------------------------------------------
  // Normalize repository files
  // --------------------------------------------------

  const contents =
    repositoryFiles.map(
      (file) => {
        const filePath =
          file.path || "";

        const parts =
          filePath.split("/");

        return {
          name:
            parts[
              parts.length - 1
            ] || filePath,

          path:
            filePath,

          type:
            "file",

          sha:
            file.sha,

          size:
            file.size || 0,

          content:
            ""
        };
      }
    );


  // --------------------------------------------------
  // Load relevant source contents
  // --------------------------------------------------

  const relevantFiles =
    contents.filter(
      (file) =>
        shouldLoadContent(
          file.path
        )
    );


  for (
    const file of relevantFiles
  ) {
    try {
      file.content =
        await loadBlobContent(
          octokit,
          owner,
          repo,
          file.sha
        );
    } catch (error) {
      console.warn(
        `Unable to load ${file.path}: ${error.message}`
      );

      file.content = "";
    }
  }


  // --------------------------------------------------
  // Root package.json
  // --------------------------------------------------

  const rootPackage =
    contents.find(
      (file) =>
        String(
          file.path || ""
        )
          .replace(/\\/g, "/")
          .toLowerCase() ===
        "package.json"
    );

  const packageContent =
    rootPackage?.content ||
    "";


  // --------------------------------------------------
  // Run ArchitectConnect
  // --------------------------------------------------

  return analyzeRepositoryContents(
    contents,
    packageContent,
    {
      repository:
        `${owner}/${repo}`,

      branch:
        defaultBranch,

      treeSha
    }
  );
}


