function isArchitectureRelevant(
  path
) {

  const normalized =
    String(path || "")
      .replace(/\\/g, "/")
      .toLowerCase();


  const fileName =
    normalized
      .split("/")
      .pop();


  if (!fileName) {

    return false;
  }


  // ========================================================
  // NODE / JAVASCRIPT / TYPESCRIPT SOURCE
  // ========================================================

  if (
    normalized.endsWith(".js") ||
    normalized.endsWith(".jsx") ||
    normalized.endsWith(".ts") ||
    normalized.endsWith(".tsx") ||
    normalized.endsWith(".mjs") ||
    normalized.endsWith(".cjs")
  ) {

    return true;
  }


  // ========================================================
  // PYTHON SOURCE
  // ========================================================

  if (
    normalized.endsWith(".py")
  ) {

    return true;
  }


  // ========================================================
  // DEPENDENCY / PROJECT FILES
  // ========================================================

  const exactFiles =
    new Set([
      "package.json",
      "requirements.txt",
      "pyproject.toml",
      "pipfile",
      "pipfile.lock",
      "poetry.lock",
      "uv.lock",
      "setup.py",
      "setup.cfg",
      "pom.xml",
      "build.gradle",
      "build.gradle.kts",
      "dockerfile",
      "docker-compose.yml",
      "docker-compose.yaml"
    ]);


  if (
    exactFiles.has(
      fileName
    )
  ) {

    return true;
  }


  // ========================================================
  // TERRAFORM
  // ========================================================

  if (
    normalized.endsWith(".tf") ||
    normalized.endsWith(".tfvars")
  ) {

    return true;
  }


  // ========================================================
  // BICEP
  // ========================================================

  if (
    normalized.endsWith(".bicep")
  ) {

    return true;
  }


  // ========================================================
  // YAML / KUBERNETES / DEPLOYMENT
  // ========================================================

  if (
    normalized.endsWith(".yaml") ||
    normalized.endsWith(".yml")
  ) {

    return true;
  }


  return false;
}


function selectArchitectureFiles(
  tree
) {

  if (!Array.isArray(tree)) {

    return [];
  }


  return tree
    .filter(
      (item) =>
        item &&
        item.type === "file" &&
        typeof item.path === "string"
    )
    .filter(
      (item) =>
        isArchitectureRelevant(
          item.path
        )
    )
    .map(
      (item) =>
        item.path
    );
}


