  isArchitectureRelevant,
  selectArchitectureFiles
};

const SCM_BRIDGE_URL =
  process.env.SCM_BRIDGE_URL ||
  "http://localhost:3000";


async function request(
  endpoint,
  parameters = {}
) {

  const url =
    new URL(
      endpoint,
      SCM_BRIDGE_URL
    );


  for (
    const [key, value]
    of Object.entries(parameters)
  ) {

    if (
      value !== undefined &&
      value !== null &&
      value !== ""
    ) {

      url.searchParams.set(
        key,
        String(value)
      );
    }
  }


  const response =
    await fetch(
      url,
      {
        method:
          "GET",

        headers: {
          Accept:
            "application/json"
        }
      }
    );


  if (!response.ok) {

    const body =
      await response.text();


    throw new Error(
      `SCM Bridge request failed. Status: ${response.status}. ${body}`
    );
  }


  return response.json();
}

