async function getArchitectureContext(
  repositoryUrl
) {

  const repositoryResponse =
    await getRepository(
      repositoryUrl
    );


  const repository =
    repositoryResponse.repository;


  if (!repository) {

    throw new Error(
      "SCM Bridge did not return repository metadata."
    );
  }


  const ref =
    repository.defaultBranch;


  if (!ref) {

    throw new Error(
      "Repository default branch is not available."
    );
  }


  const treeResponse =
    await getTree(
      repositoryUrl,
      ref
    );


  return {
    provider:
      repositoryResponse.provider,

    repository,

    ref,

    tree:
      treeResponse.tree ?? []
  };
}

async function getFiles(
  repositoryUrl,
  paths,
  ref
) {

  const files =
    [];


  for (const path of paths) {

    const response =
      await getContent(
        repositoryUrl,
        path,
        ref
      );


    const file =
      response.content?.[0];


    if (file) {

      files.push(
        file
      );
    }
  }


  return files;
}

