async function loadRepository(
  repositoryUrl
) {

  if (
    !repositoryUrl ||
    typeof repositoryUrl !== "string"
  ) {

    throw new Error(
      "Repository URL is required."
    );
  }


  // ========================================================
  // Repository metadata + tree
  // ========================================================

  const context =
    await scmBridge.getArchitectureContext(
      repositoryUrl
    );


  // ========================================================
  // Select files relevant to architecture analysis
  // ========================================================

  const selectedPaths =
    selectArchitectureFiles(
      context.tree
    );


  // ========================================================
  // Retrieve file contents through SCM Bridge
  // ========================================================

  const files =
    await scmBridge.getFiles(
      repositoryUrl,
      selectedPaths,
      context.ref
    );


  // ========================================================
  // Normalize for repositoryScanner.js
  // ========================================================

  const contents =
    files.map(
      (file) => ({

        name:
          file.path
            ?.split("/")
            .pop() ??
          file.name ??
          "",

        path:
          file.path ??
          file.name ??
          "",

        type:
          file.type ??
          "file",

        size:
          file.size,

        sha:
          file.sha,

        content:
          typeof file.content === "string"
            ? file.content
            : ""
      })
    );


  // ========================================================
  // Root package.json
  //
  // Existing repositoryScanner() accepts packageContent
  // separately, so preserve that contract.
  // ========================================================

  const rootPackageFile =
    contents.find(
      (item) =>
        item.path
          .replace(/\\/g, "/")
          .toLowerCase() ===
        "package.json"
    );


  const packageContent =
    rootPackageFile &&
    typeof rootPackageFile.content === "string"
      ? rootPackageFile.content
      : "";


  return {
    provider:
      context.provider,

    repository:
      context.repository,

    ref:
      context.ref,

    tree:
      context.tree,

    selectedPaths,

    contents,

    packageContent
  };
}


