      relationship.relationship ===
      "handled_by"
        ? "Handled by"
        : relationship.relationship ===
            "uses"
          ? "Uses"
          : (
              relationship.relationship ||
              "Depends on"
            );


    // ==================================================
    // API -> COMPONENT
    // ==================================================
    //
    // Structurizr does not allow a parent container
    // to have a relationship directly to its own
    // component.
    //
    // Therefore, when a frontend is available, expose
    // the API interaction from the frontend to the
    // discovered request-handler component.
    //
    // ==================================================

    if (
      relationship.fromType ===
        "api" &&
      relationship.to
    ) {
      const targetId =
        findElementId(
          applicationKey,
          relationship.to
        );


      if (
        !targetId
      ) {
        continue;
      }


      if (
        frontendId
      ) {
        modelRelationships += `
        ${frontendId} -> ${targetId} "${escapeDsl(
          relationship.from
        )}"
`;


        applicationsWithApiRelationships.add(
          applicationKey
        );
      }


      continue;
    }


    // ==================================================
    // COMPONENT -> COMPONENT
    // ==================================================

    const fromId =
      findElementId(
        applicationKey,
        relationship.from
      );


    const toId =
      findElementId(
        applicationKey,
        relationship.to
      );


    if (
      !fromId ||
      !toId
    ) {
      continue;
    }


    modelRelationships += `
        ${fromId} -> ${toId} "${escapeDsl(
          relationshipLabel
        )}"
`;
  }


  // ==================================================
  // FALLBACK FRONTEND -> APPLICATION
  // ==================================================
  //
  // Only generate a generic frontend-to-application
  // relationship when no precise API relationship was
  // discovered for that application.
  //
  // Do not generate frontend -> frontend relationships.
  //
  // ==================================================

  if (
    frontendId
  ) {
    for (
      const applicationItem of
      applications
    ) {
      if (
        !applicationItem
      ) {
        continue;
      }


      const applicationKey =
        getApplicationKey(
          applicationItem
        );


      if (
        !applicationKey
      ) {
        continue;
      }


      const applicationId =
        applicationIds.get(
          applicationKey
        );


      if (
        !applicationId
      ) {
        continue;
      }


      if (
        applicationItem.type ===
        "frontend"
      ) {
        continue;
      }


      if (
        applicationsWithApiRelationships.has(
          applicationKey
        )
      ) {
        continue;
      }


      modelRelationships += `
        ${frontendId} -> ${applicationId} "Calls API"
`;
    }
  }


  // ==================================================
  // APPLICATION -> DOCKER
  // ==================================================

  if (
    hasDocker
  ) {
    for (
      const applicationItem of
      applications
    ) {
      if (
        !applicationItem
      ) {
        continue;
      }


      const applicationKey =
        getApplicationKey(
          applicationItem
        );


      if (
        !applicationKey
      ) {
        continue;
      }


      const appId =
        applicationIds.get(
          applicationKey
        );


      if (
        !appId
      ) {
        continue;
      }


      modelRelationships += `
        ${appId} -> docker "Packaged as"
`;
    }
  }


  // ==================================================
  // DOCKER -> KUBERNETES
  // ==================================================

  if (
    hasDocker &&
    hasKubernetes
  ) {
    modelRelationships += `
        docker -> kubernetes "Deployed to"
`;
  }


  // ==================================================
  // TERRAFORM -> KUBERNETES
  // ==================================================

  if (
    hasTerraform &&
    hasKubernetes
  ) {
    modelRelationships += `
        terraform -> kubernetes "Provisions supporting infrastructure"
`;
  }


  // ==================================================
  // BICEP -> KUBERNETES
  // ==================================================

  if (
    hasBicep &&
    hasKubernetes
  ) {
    modelRelationships += `
        bicep -> kubernetes "Defines Azure infrastructure"
`;
  }


  // ==================================================
  // COMPONENT VIEW GENERATION
  // ==================================================

  let componentViews =
    "";


  for (
    const applicationItem of
    applications
  ) {
    if (
      !applicationItem
    ) {
      continue;
    }


    const applicationKey =
      getApplicationKey(
        applicationItem
      );


    if (
      !applicationKey
    ) {
      continue;
    }


    const applicationId =
      applicationIds.get(
        applicationKey
      );


    if (
      !applicationId
    ) {
      continue;
    }


    const applicationName =
      getApplicationName(
        applicationItem
      );


    const applicationComponents =
      components.filter(
        (component) => {
          if (
            !component
          ) {
            return false;
          }


          const rawComponentApplicationKey =
            getItemApplicationKey(
              component
            );


          const componentApplicationKey =
            resolveApplicationKey(
              rawComponentApplicationKey
            );


          if (
            componentApplicationKey ===
            applicationKey
          ) {
            return true;
          }


          return (
            component.application &&
            component.application ===
              applicationName
          );
        }
      );


    if (
      applicationComponents.length ===
      0
    ) {
      continue;
    }


    const viewKey =
      sanitizeId(
        `${applicationKey}_Components`
      );


    componentViews += `
        component ${applicationId} "${viewKey}" {
            include *
            autoLayout
        }
`;
  }


  // ==================================================
  // STRUCTURIZR DSL
  // ==================================================

  return `
workspace "ArchitectConnect Architecture" {

    model {

${modelElements}

${modelRelationships}

    }

    views {

        systemContext application "SystemContext" {
            include *
            autoLayout
        }

        container application "ApplicationContainers" {
            include *
            autoLayout
        }

${componentViews}

        systemLandscape "DeploymentInfrastructure" {
            include *
            autoLayout
        }

        styles {

            element "Person" {
                shape person
                background #08427B
                color #ffffff
            }

            element "Frontend" {
                background #6B5B95
                color #ffffff
            }

            element "Application" {
                background #438DD5
                color #ffffff
            }

            element "Component" {
                background #85BB65
                color #000000
            }

            element "Deployment" {
                background #5D8AA8
                color #ffffff
            }

            element "Infrastructure" {
                background #999999
                color #ffffff
            }
        }
    }
}
`;
}


