          application.type ||
          "Not detected"
        }`
      );


      console.log(
        `  Language: ${
          application.language ||
          "Not detected"
        }`
      );


      console.log(
        `  Runtime: ${
          application.runtime ||
          "Not detected"
        }`
      );


      console.log(
        `  Framework: ${
          application.framework ||
          "Not detected"
        }`
      );
    }
  }


  // ==================================================
  // API DETAILS
  // ==================================================

  console.log(
    "\nAPIs:"
  );


  if (
    selectedApis.length ===
    0
  ) {

    console.log(
      "- No APIs detected"
    );

  } else {

    for (
      const api of
      selectedApis
    ) {

      console.log(
        `- ${
          api.method ||
          "UNKNOWN"
        } ${
          api.path ||
          "Unknown"
        }`
      );


      console.log(
        `  Framework: ${
          api.framework ||
          "Not detected"
        }`
      );


      if (
        api.handler
      ) {

        console.log(
          `  Handler: ${api.handler}`
        );
      }


      console.log(
        `  Source: ${
          api.source ||
          "Unknown"
        }`
      );
    }
  }


  // ==================================================
  // COMPONENT DETAILS
  // ==================================================

  console.log(
    "\nComponents:"
  );


  if (
    selectedComponents.length ===
    0
  ) {

    console.log(
      "- No components detected"
    );

  } else {

    for (
      const component of
      selectedComponents
    ) {

      if (
        typeof component ===
        "string"
      ) {

        console.log(
          `- ${component}`
        );

        continue;
      }


      console.log(
        `- ${
          component.name ||
          "Component"
        } [${
          component.type ||
          component.role ||
          "unknown"
        }]`
      );


      if (
        component.applicationRoot
      ) {

        console.log(
          `  Application: ${component.applicationRoot}`
        );
      }


      if (
        component.source
      ) {

        console.log(
          `  Source: ${component.source}`
        );
      }
    }
  }


  // ==================================================
  // RELATIONSHIP DETAILS
  // ==================================================

  console.log(
    "\nRelationships:"
  );


  if (
    selectedRelationships.length ===
    0
  ) {

    console.log(
      "- No architecture relationships detected"
    );

  } else {

    for (
      const relationship of
      selectedRelationships
    ) {

      console.log(
        `- ${
          relationship.from ||
          "Unknown"
        } -> ${
          relationship.to ||
          "Unknown"
        }`
      );


      console.log(
        `  ${
          relationship.fromType ||
          "unknown"
        } -> ${
          relationship.toType ||
          "unknown"
        }`
      );


      console.log(
        `  Relationship: ${
          relationship.relationship ||
          "depends_on"
        }`
      );


      if (
        relationship.applicationRoot
      ) {

        console.log(
          `  Application: ${relationship.applicationRoot}`
        );
      }


      if (
        relationship.evidence
      ) {

        console.log(
          `  Evidence: ${relationship.evidence}`
        );
      }
    }
  }


  // ==================================================
  // ARCHITECTURE ASSESSMENT
  // ==================================================

  console.log(
    "\nArchitecture Assessment:"
  );


  console.log(
    "Gaps:",
    Array.isArray(
      findings.gaps
    )
      ? findings.gaps.length
      : 0
  );


  console.log(
    "Assumptions:",
    Array.isArray(
      findings.assumptions
    )
      ? findings.assumptions.length
      : 0
  );


  console.log(
    "Score:",
    `${
      typeof findings.architectureScore ===
      "number"
        ? findings.architectureScore
        : 0
    }/100`
  );


  // ==================================================
  // GENERATED ARCHITECTURE ARTIFACTS
  // ==================================================

  console.log(
    "\nGenerated Architecture Artifacts:"
  );


  console.log(
    "HLD generated:",
    hldGenerated
      ? "YES"
      : "NO"
  );


  console.log(
    "HLD clean:",
    hldClean
      ? "YES"
      : "NO"
  );


  console.log(
    "DSL generated:",
    dslGenerated
      ? "YES"
      : "NO"
  );


  console.log(
    "DSL clean:",
    dslClean
      ? "YES"
      : "NO"
  );


  // ==================================================
  // GENERATED FILES
  // ==================================================

  console.log(
    "\nGenerated Files:"
  );


  console.log(
    "Architecture HLD:"
  );


  console.log(
    hldGenerated
      ? hldFilePath
      : "Not generated"
  );


  console.log(
    "Structurizr DSL:"
  );


  console.log(
    dslGenerated
      ? dslFilePath
      : "Not generated"
  );


  // ==================================================
  // FAIL TEST IF OUTPUT IS INVALID
  // ==================================================

  if (
    !hldGenerated ||
    !dslGenerated ||
    !hldClean ||
    !dslClean
  ) {

    throw new Error(
      "Generated architecture artifacts failed validation."
    );
  }


  // ==================================================
  // PROPOSED ARCHITECTURE DECISION RECORDS
  // ==================================================

  console.log(
    "\n========== PROPOSED ADRs =========="
  );


  if (
    Array.isArray(
      result.adrs
    ) &&
    result.adrs.length > 0
  ) {

    console.log(
      "Generated:",
      result.adrs.length
    );


    for (
      const adr of
      result.adrs
    ) {

      console.log(
        `\n${adr.id}: ${adr.title}`
      );


      console.log(
        `Status: ${adr.status}`
      );


      console.log(
        `Decision: ${adr.decision}`
      );


      console.log(
        `Context: ${adr.context}`
      );


      console.log(
        "Evidence:"
      );


      if (
        Array.isArray(
          adr.evidence
        ) &&
        adr.evidence.length > 0
      ) {

        for (
          const evidence of
          adr.evidence
        ) {

          console.log(
            `- ${evidence}`
          );
        }

      } else {

        console.log(
          "- No specific repository file evidence recorded"
        );
      }


      console.log(
        `Rationale: ${adr.rationale}`
      );


      console.log(
        `Alternatives: ${adr.alternatives}`
      );


      if (
        adr.consequences &&
        Array.isArray(
          adr.consequences.observed
        ) &&
        adr.consequences.observed.length > 0
      ) {

        console.log(
          "Observed consequences:"
        );


        for (
          const consequence of
          adr.consequences.observed
        ) {

          console.log(
            `- ${consequence}`
          );
        }
      }


      if (
        Array.isArray(
          adr.validationQuestions
        ) &&
        adr.validationQuestions.length > 0
      ) {

        console.log(
          "Validation questions:"
        );


        for (
          const question of
          adr.validationQuestions
        ) {

          console.log(
            `- ${question}`
          );
        }
      }


      console.log(
        `Architect validation required: ${
          adr.requiresValidation
            ? "YES"
            : "NO"
        }`
      );
    }

  } else {

    console.log(
      "No proposed ADRs generated."
    );
  }


  console.log(
    "\n===================================\n"
  );

} // async function test() closes here


// ==================================================
// RUN
// ==================================================

test().catch(
  (error) => {

    console.error(
      "\nSERVICE TEST FAILED:\n"
    );


    console.error(
      error
    );


    process.exitCode =
      1;
  }
);
